/// Two identical pips of one color for the shipped five-color option bag.
fn doubled_mana_amount(symbol: char) -> Option<ManaAmount> {
    let mut amount = parse_mana_amount(symbol)?;
    for value in [
        &mut amount.w,
        &mut amount.u,
        &mut amount.b,
        &mut amount.r,
        &mut amount.g,
        &mut amount.c,
    ] {
        *value *= 2;
    }
    Some(amount)
}

