fn exact_mana_cost(text: &str) -> Option<ManaCost> {
    if text.is_empty() {
        return None;
    }
    let cost = ManaCost::parse(text).ok()?;
    (!cost.has_x() && cost.to_string() == text).then_some(cost)
}

