/// CR 702.29a: Cycling is a hand-zone activated ability. The exact printed line is either the
/// bare `Cycling {cost}` form or the fixed reminder form `Cycling {cost} ({cost}, Discard this
/// card: Draw a card.)`. The reminder body must repeat the same cost and the exact draw-one
/// instruction; a mismatched cost, another parenthetical, or an appended instruction stays
/// unsupported. Issue #413 names the recipe `cycling.draw.reminder` and matches both forms with
/// one activator and one emission.
fn match_cycling_draw(text: &str, context: &RecipeContext) -> Option<RecipeEmission> {
    let body = text.strip_prefix("Cycling ")?;
    let cost = match body.split_once(" (") {
        Some((printed_cost, reminder)) => {
            let cost = exact_mana_cost(printed_cost)?;
            (reminder == format!("{}, Discard this card: Draw a card.)", cost)).then_some(cost)?
        }
        None => exact_mana_cost(body)?,
    };
    Some(hand_discard_ability(
        context,
        cost,
        SpellEffectKind::Draw {
            who: PlayerRecipient::Controller,
            count: Amount::Fixed(1),
        },
    ))
}

fn typecycling_search(
    context: &RecipeContext,
    mana_cost: ManaCost,
    filter: ZoneCardFilter,
) -> RecipeEmission {
    hand_discard_ability(
        context,
        mana_cost,
        SpellEffectKind::SearchLibrary {
            who: PlayerRecipient::Controller,
            optional: false,
            count: 1,
            count_by_cast_cost: None,
            filter: Some(filter),
            slots: Vec::new(),
            zones: SearchZoneSelection::default(),
            destination: SearchDestination::Hand,
            conditional_destination: None,
            shuffle: true,
            reveal: true,
            result_id: None,
        },
    )
}

fn match_basic_landcycling(text: &str, context: &RecipeContext) -> Option<RecipeEmission> {
    let cost = exact_mana_cost(text.strip_prefix("Basic landcycling ")?)?;
    Some(typecycling_search(
        context,
        cost,
        ZoneCardFilter {
            card_type: Some(CardTypeFilter::BasicLand),
            ..ZoneCardFilter::default()
        },
    ))
}

fn match_basic_land_typecycling(text: &str, context: &RecipeContext) -> Option<RecipeEmission> {
    let (land_type, cost) = BasicLandType::ALL.into_iter().find_map(|land_type| {
        let prefix = format!("{}cycling ", land_type.as_str());
        let cost = exact_mana_cost(text.strip_prefix(&prefix)?)?;
        Some((land_type, cost))
    })?;
    Some(typecycling_search(
        context,
        cost,
        ZoneCardFilter {
            required_subtypes: vec![land_type.as_str().to_string()],
            ..ZoneCardFilter::default()
        },
    ))
}

