    fn assert_modal_mode(clause: &str, expected_id: &str) -> ModalModeEmission {
        let matched = match_modal_mode(clause, &context())
            .unwrap_or_else(|error| panic!("{clause}: {error}"))
            .unwrap_or_else(|| panic!("missing modal_mode recipe for {clause}"));
        assert_eq!(matched.id.as_str(), expected_id, "{clause}");
        let RecipeEmission::ModalMode(emission) = matched.emission else {
            panic!("{expected_id} must emit a modal mode");
        };
        emission
    }

    #[test]
    fn issue_412_modal_mode_recipes_match_their_exact_clauses() {
        // The power-based damage mode already ships as
        // `modal_mode.damage.creature.equal_power.controlled_to_opponent`; issue #412's proposed
        // second id would be a duplicate clause owner and an ambiguity error, so this batch keeps
        // the shipped recipe and proves HULK SMASH!'s printed bullet routes to it.
        for (clause, expected_id) in [
            (
                "Destroy target enchantment.",
                "modal_mode.destroy.enchantment",
            ),
            (
                "Destroy target creature with power 4 or greater.",
                "modal_mode.destroy.creature.power_at_least_four",
            ),
            (
                "Target creature you control fights target creature an opponent controls.",
                "modal_mode.fight.controlled_vs_opponent",
            ),
            (
                "Target creature you control deals damage equal to its power to target creature an opponent controls.",
                "modal_mode.damage.creature.equal_power.controlled_to_opponent",
            ),
            ("Destroy target Vehicle.", "modal_mode.destroy.vehicle"),
            (
                "Exile up to one target card from a graveyard. Draw a card.",
                "modal_mode.exile.graveyard_card_up_to_one.draw_one",
            ),
            ("Draw a card.", "modal_mode.draw.one"),
            (
                "Draw a card. Create a Food token.",
                "modal_mode.draw.one.create_food",
            ),
            (
                "You gain 3 life and surveil 3.",
                "modal_mode.gain_life.three.surveil.three",
            ),
            (
                "Counter target creature spell.",
                "modal_mode.counter.creature_spell",
            ),
            (
                "Create a 2/2 black and green Elf creature token.",
                "modal_mode.create_token.elf_black_green.two_two",
            ),
        ] {
            let matched = match_modal_mode(clause, &context())
                .unwrap_or_else(|error| panic!("{clause}: {error}"))
                .unwrap_or_else(|| panic!("missing modal_mode recipe for {clause}"));
            assert_eq!(matched.id.as_str(), expected_id, "{clause}");
        }

        for recipe_id in [
            "modal_mode.destroy.enchantment",
            "modal_mode.destroy.creature.power_at_least_four",
            "modal_mode.fight.controlled_vs_opponent",
            "modal_mode.destroy.vehicle",
            "modal_mode.exile.graveyard_card_up_to_one.draw_one",
            "modal_mode.draw.one",
            "modal_mode.draw.one.create_food",
            "modal_mode.gain_life.three.surveil.three",
            "modal_mode.counter.creature_spell",
            "modal_mode.create_token.elf_black_green.two_two",
        ] {
            let recipe = CATALOG
                .iter()
                .find(|recipe| recipe.id.as_str() == recipe_id)
                .unwrap_or_else(|| panic!("missing issue #412 recipe {recipe_id}"));
            assert_eq!(recipe.surface, RecipeSurface::ModalMode, "{recipe_id}");
        }
    }

    #[test]
    fn issue_412_modal_mode_recipes_emit_typed_payloads() {
        assert_eq!(
            assert_modal_mode(
                "Destroy target enchantment.",
                "modal_mode.destroy.enchantment"
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::Destroy {
                    subject: EffectSubject::Chosen(Box::new(TargetFilter {
                        kind: TargetKind::AnyPermanent,
                        permanent_types: vec![PermanentTypeFilter::Enchantment],
                        ..TargetFilter::default()
                    })),
                }],
                targeting: modal_targeting("Choose target enchantment", 0),
            }
        );
        assert_eq!(
            assert_modal_mode(
                "Destroy target creature with power 4 or greater.",
                "modal_mode.destroy.creature.power_at_least_four",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::Destroy {
                    subject: EffectSubject::Chosen(Box::new(TargetFilter {
                        kind: TargetKind::Creature,
                        power: Some(tricerules_cards::PowerComparison::AtLeast(4)),
                        ..TargetFilter::default()
                    })),
                }],
                targeting: modal_targeting("Choose target creature with power 4 or greater", 0),
            }
        );
        assert_eq!(
            assert_modal_mode(
                "Target creature you control fights target creature an opponent controls.",
                "modal_mode.fight.controlled_vs_opponent",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::Fight {
                    first: EffectSubject::Chosen(Box::new(TargetFilter {
                        kind: TargetKind::Creature,
                        controller: TargetController::You,
                        ..TargetFilter::default()
                    })),
                    second: EffectSubject::Chosen(Box::new(TargetFilter {
                        kind: TargetKind::Creature,
                        controller: TargetController::Opponent,
                        ..TargetFilter::default()
                    })),
                }],
                targeting: modal_targeting_groups(vec![
                    ("Choose target creature you control", vec![0]),
                    ("Choose target creature an opponent controls", vec![0]),
                ]),
            }
        );
        assert_eq!(
            assert_modal_mode("Destroy target Vehicle.", "modal_mode.destroy.vehicle"),
            ModalModeEmission {
                effects: vec![SpellEffectKind::Destroy {
                    subject: EffectSubject::Chosen(Box::new(TargetFilter {
                        kind: TargetKind::AnyPermanent,
                        required_subtypes: vec!["Vehicle".into()],
                        ..TargetFilter::default()
                    })),
                }],
                targeting: modal_targeting("Choose target Vehicle", 0),
            }
        );
        assert_eq!(
            assert_modal_mode(
                "Exile up to one target card from a graveyard. Draw a card.",
                "modal_mode.exile.graveyard_card_up_to_one.draw_one",
            ),
            ModalModeEmission {
                effects: vec![
                    SpellEffectKind::MoveGraveyardCards {
                        filter: GraveyardFilter {
                            owner: GraveyardOwner::AnyPlayer,
                            ..GraveyardFilter::default()
                        },
                        destination: GraveyardDestination::Exile,
                        linked_exile_id: None,
                    },
                    SpellEffectKind::Draw {
                        who: PlayerRecipient::Controller,
                        count: Amount::Fixed(1),
                    },
                ],
                targeting: Some(TargetingDef {
                    groups: vec![TargetGroupDef {
                        min: 0,
                        max: 1,
                        prompt: "Choose up to one target card from a graveyard".into(),
                        effect_indices: vec![0],
                        distinct_from: Vec::new(),
                        same_graveyard: false,
                        cast_cost_expansion: None,
                    }],
                }),
            }
        );
        assert_eq!(
            assert_modal_mode("Draw a card.", "modal_mode.draw.one"),
            ModalModeEmission {
                effects: vec![SpellEffectKind::Draw {
                    who: PlayerRecipient::Controller,
                    count: Amount::Fixed(1),
                }],
                targeting: None,
            }
        );
        assert_eq!(
            assert_modal_mode(
                "Draw a card. Create a Food token.",
                "modal_mode.draw.one.create_food",
            ),
            ModalModeEmission {
                effects: vec![
                    SpellEffectKind::Draw {
                        who: PlayerRecipient::Controller,
                        count: Amount::Fixed(1),
                    },
                    SpellEffectKind::CreateTokens {
                        token: "food".into(),
                        count: Amount::Fixed(1),
                        who: PlayerRecipient::Controller,
                        tapped: false,
                        sacrifice_timing: None,
                    },
                ],
                targeting: None,
            }
        );
        assert_eq!(
            assert_modal_mode(
                "You gain 3 life and surveil 3.",
                "modal_mode.gain_life.three.surveil.three",
            ),
            ModalModeEmission {
                effects: vec![
                    SpellEffectKind::GainLife {
                        amount: Amount::Fixed(3),
                    },
                    SpellEffectKind::LibraryPartition {
                        count: 3,
                        top_min: 0,
                        top_max: None,
                        kind: LibraryPartitionKind::Surveil,
                    },
                ],
                targeting: None,
            }
        );
        assert_eq!(
            assert_modal_mode(
                "Counter target creature spell.",
                "modal_mode.counter.creature_spell",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::CounterTargetSpell {
                    spell_filter: StackSpellFilter {
                        card_type: Some(CardTypeFilter::Creature),
                        ..StackSpellFilter::default()
                    },
                    unless_controller_pays: None,
                    unless_controller_pays_by_cast_cost: None,
                }],
                targeting: modal_targeting("Choose target creature spell", 0),
            }
        );
        assert_eq!(
            assert_modal_mode(
                "Create a 2/2 black and green Elf creature token.",
                "modal_mode.create_token.elf_black_green.two_two",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::CreateTokens {
                    token: "elf_bg_2_2".into(),
                    count: Amount::Fixed(1),
                    who: PlayerRecipient::Controller,
                    tapped: false,
                    sacrifice_timing: None,
                }],
                targeting: None,
            }
        );
    }

    #[test]
    fn issue_412_modal_mode_recipes_reject_near_misses() {
        // Appended riders, up-to-one forms, union/other-type wording, other damage bases, other
        // controller relationships, and other counts or tokens must stay unsupported.
        for clause in [
            "Destroy up to one target enchantment.",
            "Destroy target permanent.",
            "Destroy target enchantment you control.",
            "Destroy target enchantment. You gain 2 life.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "destroy.enchantment accepted {clause}"
            );
        }
        // The union and single-artifact forms stay owned by their shipped recipes instead of
        // collapsing into the new single-type matcher.
        for (clause, owner) in [
            (
                "Destroy target artifact or enchantment.",
                "modal_mode.destroy.artifact_or_enchantment",
            ),
            ("Destroy target artifact.", "modal_mode.destroy.artifact"),
        ] {
            assert_eq!(
                match_modal_mode(clause, &context())
                    .expect("cross-owner near-miss must not be ambiguous")
                    .unwrap_or_else(|| panic!(
                        "cross-owner near-miss must keep its owner: {clause}"
                    ))
                    .id
                    .as_str(),
                owner,
                "{clause}"
            );
        }

        for clause in [
            "Destroy target creature with power 3 or greater.",
            "Destroy target creature with power 4 or greater you control.",
            "Destroy target creature with power 4 or greater. You gain 2 life.",
            "Destroy up to one target creature with power 4 or greater.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "destroy.creature.power_at_least_four accepted {clause}"
            );
        }
        // The toughness sibling is a different printed restriction and keeps its own recipe.
        assert_eq!(
            match_modal_mode(
                "Destroy target creature with toughness 4 or greater.",
                &context()
            )
            .expect("the toughness sibling must not be ambiguous")
            .expect("the toughness sibling should match")
            .id
            .as_str(),
            "modal_mode.destroy.creature.toughness_at_least_four"
        );

        for clause in [
            "Target creature you control fights another target creature an opponent controls.",
            "Target creature you control fights target creature you don't control.",
            "Target creature an opponent controls fights target creature you control.",
            "Target creature fights target creature an opponent controls.",
            "Target creature you control fights up to one target creature an opponent controls.",
            "Target creature you control fights target creature an opponent controls. Untap them.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "fight.controlled_vs_opponent accepted {clause}"
            );
        }

        for clause in [
            "Target creature you control deals damage equal to its toughness to target creature an opponent controls.",
            "Target creature deals damage equal to its power to target creature an opponent controls.",
            "Target creature you control deals damage equal to its power to target creature you don't control.",
            "Target creature you control deals damage equal to its power to target creature an opponent controls. Draw a card.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "the shipped power-damage recipe accepted {clause}"
            );
        }

        for clause in [
            "Destroy up to one target Vehicle.",
            "Destroy target Vehicle you control.",
            "Destroy target noncreature Vehicle.",
            "Destroy target Vehicle. You gain 2 life.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "destroy.vehicle accepted {clause}"
            );
        }
        assert_eq!(
            match_modal_mode("Destroy target artifact.", &context())
                .expect("cross-owner near-miss must not be ambiguous")
                .expect("the single-artifact bullet keeps its shipped owner")
                .id
                .as_str(),
            "modal_mode.destroy.artifact"
        );

        for clause in [
            "Exile up to one target card from your graveyard. Draw a card.",
            "Exile up to one target card from an opponent's graveyard. Draw a card.",
            "Exile target card from a graveyard. Draw a card.",
            "Exile up to one target creature card from a graveyard. Draw a card.",
            "Exile up to two target cards from a graveyard. Draw a card.",
            "Exile up to one target card from a graveyard.",
            "Exile up to one target card from a graveyard. Draw two cards.",
            "Exile up to one target card from a graveyard. You gain 1 life.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "exile.graveyard_card_up_to_one.draw_one accepted {clause}"
            );
        }

        for clause in [
            "Draw five cards.",
            "Draw a card. You gain 1 life.",
            "Draw a card. Create a Treasure token.",
            "Each player draws a card.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "draw.one accepted {clause}"
            );
        }
        // `Draw a card. Create a Food token.` owns its own recipe; an overlapping plain-draw
        // matcher would surface here as an ambiguity error instead of the exact owner.
        assert_eq!(
            assert_modal_mode(
                "Draw a card. Create a Food token.",
                "modal_mode.draw.one.create_food",
            )
            .effects
            .len(),
            2,
            "draw.one must stay disjoint from draw.one.create_food"
        );

        for clause in [
            "Draw a card. Create a Treasure token.",
            "Draw two cards. Create a Food token.",
            "Create a Food token. Draw a card.",
            "Draw a card, then create a Food token.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "draw.one.create_food accepted {clause}"
            );
        }

        for clause in [
            "You gain 7 life and surveil 3.",
            "You gain 2 life and surveil 3.",
            "You gain 3 life and surveil 2.",
            "You gain 3 life, then surveil 3.",
            "You gain 3 life and surveil 3, then draw a card.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "gain_life.three.surveil.three accepted {clause}"
            );
        }

        for clause in [
            "Counter target noncreature spell.",
            "Counter up to one target creature spell.",
            "Counter target creature spell unless its controller pays {2}.",
            "Counter target creature spell. Draw a card.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "counter.creature_spell accepted {clause}"
            );
        }
        assert_eq!(
            match_modal_mode("Counter target spell.", &context())
                .expect("cross-owner near-miss must not be ambiguous")
                .expect("the unrestricted counter keeps its shipped owner")
                .id
                .as_str(),
            "modal_mode.counter.spell.unrestricted"
        );

        for clause in [
            "Create a 2/2 green Elf creature token.",
            "Create a 2/2 black and green Elf Warrior creature token.",
            "Create two 2/2 black and green Elf creature tokens.",
            "Create a tapped 2/2 black and green Elf creature token.",
            "Create a 2/2 black and green Elf creature token. Draw a card.",
        ] {
            assert!(
                match_modal_mode(clause, &context())
                    .expect("near-miss must not be ambiguous")
                    .is_none(),
                "create_token.elf_black_green.two_two accepted {clause}"
            );
        }
    }

    // -----------------------------------------------------------------------
    // Issue #414 — enters-with-minus-counter creature cohort.
    // -----------------------------------------------------------------------

    const ISSUE_414_BURDENED_STONEBACK_ORACLE_ID: &str = "8a5e17a0-6f3c-49ed-b328-ed90a46ed6c5";
    const ISSUE_414_MOONLIT_LAMENTER_ORACLE_ID: &str = "ce009bd4-5ffb-46a4-a9dd-b9c060926467";
    const ISSUE_414_HOVEL_HURLER_ORACLE_ID: &str = "fb9cd9d0-8eea-4aa8-bb9c-bb0aac847421";
    const ISSUE_414_GNARLBARK_ELM_ORACLE_ID: &str = "a848ea46-347d-49c7-85c8-023cf836d0b3";
    const ISSUE_414_REAPING_WILLOW_ORACLE_ID: &str = "ce60402c-34cd-44fe-ae1d-4a5404298f5b";
    const ISSUE_414_GNARLBARK_ELM_CLAUSE: &str = "{2}{B}, Remove two counters from this creature: Target creature gets -2/-2 until end of turn. Activate only as a sorcery.";
    const ISSUE_414_REAPING_WILLOW_CLAUSE: &str = "{1}{W/B}, Remove two counters from this creature: Return target creature card with mana value 3 or less from your graveyard to the battlefield. Activate only as a sorcery.";

    fn issue_414_context(oracle_id: &str, source_name: &str) -> RecipeContext {
        let mut context = context();
        context.oracle_id = Some(oracle_id.into());
        context.source_name = source_name.into();
        context
    }

    #[test]
    fn issue_414_enters_with_one_and_two_minus_one_counters_are_generic_exact_templates() {
        for (clause, expected_amount, corpus_printings) in [
            (
                ISSUE_414_ENTERS_WITH_TWO_CLAUSE,
                2,
                &[
                    "Brambleback Brute",
                    "Burdened Stoneback",
                    "Carnifex Demon",
                    "Chainbreaker",
                    "Deity of Scars",
                    "Gnarlbark Elm",
                    "Heirloom Auntie",
                    "Hovel Hurler",
                    "Leech Bonder",
                    "Morselhoarder",
                    "Reaping Willow",
                    "Reluctant Dounguard",
                    "Slumbering Walker",
                ][..],
            ),
            (
                ISSUE_414_ENTERS_WITH_ONE_CLAUSE,
                1,
                &[
                    "Bloodied Ghost",
                    "Flitterwing Nuisance",
                    "Glen Elendra Guardian",
                    "Moonlit Lamenter",
                    "Wickerbough Elder",
                ][..],
            ),
        ] {
            for source_name in corpus_printings {
                let mut source = context();
                source.source_name = (*source_name).into();
                let matched = match_clause(clause, false, &source)
                    .unwrap_or_else(|ambiguity| panic!("{clause}: {ambiguity}"))
                    .unwrap_or_else(|| {
                        panic!("{source_name} should match the {expected_amount}-counter recipe")
                    });
                assert_eq!(
                    matched.id.as_str(),
                    match expected_amount {
                        1 => "static.enters_with.minus_one_minus_one.one",
                        _ => "static.enters_with.minus_one_minus_one.two",
                    },
                    "{clause}"
                );
                let RecipeEmission::StaticAbility(ability) = matched.emission else {
                    panic!("expected a static ability, got {:?}", matched.emission);
                };
                assert_eq!(
                    ability.definition,
                    StaticAbilityDef::EntersWithCounters {
                        affected: EntersWithCountersAffected::Self_,
                        counter: CounterKind::MinusOneMinusOne,
                        amount: Amount::Fixed(expected_amount),
                        cast_cost_condition: None,
                    }
                );
            }
        }
    }

    #[test]
    fn issue_414_retained_remove_counter_activations_are_exact_singletons() {
        // 1. Burdened Stoneback: {1}{W} plus removing any one counter from the source buys an
        // indestructible grant on one target creature at sorcery speed.
        let matched = match_clause(
            ISSUE_414_BURDENED_STONEBACK_CLAUSE,
            false,
            &issue_414_context(ISSUE_414_BURDENED_STONEBACK_ORACLE_ID, "Burdened Stoneback"),
        )
        .expect("Burdened Stoneback clause must not be ambiguous")
        .expect("Burdened Stoneback clause must match");
        assert_eq!(
            matched.id.as_str(),
            "ability.remove_counter.grant_indestructible.one"
        );
        let RecipeEmission::ActivatedAbility(ability) = matched.emission else {
            panic!("expected an activated ability, got {:?}", matched.emission);
        };
        assert_eq!(ability.source_zone, AbilitySourceZone::Battlefield);
        assert_eq!(
            ability.costs,
            vec![
                AbilityCost::Mana(ManaCost::parse("{1}{W}").expect("printed mana cost")),
                AbilityCost::RemoveCounters {
                    counter: None,
                    count: 1,
                    payment_source: CounterRemovalPaymentSource::Source,
                },
            ]
        );
        assert_eq!(
            ability.effect,
            vec![SpellEffectKind::GrantKeywords {
                subject: EffectSubject::Chosen(Box::new(TargetFilter::default_creature())),
                keywords: vec![Keyword::Indestructible],
            }]
        );
        assert_eq!(ability.timing, ActivationTiming::SorcerySpeed);
        assert_eq!(
            ability.targeting,
            Some(exact_targeting(1, 1, "Choose target creature", vec![0]))
        );

        // 2. Moonlit Lamenter: {1}{W} plus removing any one counter from the source draws a card at
        // sorcery speed without targeting.
        let matched = match_clause(
            ISSUE_414_MOONLIT_LAMENTER_CLAUSE,
            false,
            &issue_414_context(ISSUE_414_MOONLIT_LAMENTER_ORACLE_ID, "Moonlit Lamenter"),
        )
        .expect("Moonlit Lamenter clause must not be ambiguous")
        .expect("Moonlit Lamenter clause must match");
        assert_eq!(matched.id.as_str(), "ability.remove_counter.draw_one.one");
        let RecipeEmission::ActivatedAbility(ability) = matched.emission else {
            panic!("expected an activated ability, got {:?}", matched.emission);
        };
        assert_eq!(ability.source_zone, AbilitySourceZone::Battlefield);
        assert_eq!(
            ability.costs,
            vec![
                AbilityCost::Mana(ManaCost::parse("{1}{W}").expect("printed mana cost")),
                AbilityCost::RemoveCounters {
                    counter: None,
                    count: 1,
                    payment_source: CounterRemovalPaymentSource::Source,
                },
            ]
        );
        assert_eq!(
            ability.effect,
            vec![SpellEffectKind::Draw {
                who: PlayerRecipient::Controller,
                count: Amount::Fixed(1),
            }]
        );
        assert_eq!(ability.timing, ActivationTiming::SorcerySpeed);
        assert_eq!(ability.targeting, None);

        // 3. Hovel Hurler: the hybrid {R/W}{R/W} plus one counter pumps a *different* creature its
        // controller controls +1/+0 and grants flying to that same target.
        let matched = match_clause(
            ISSUE_414_HOVEL_HURLER_CLAUSE,
            false,
            &issue_414_context(ISSUE_414_HOVEL_HURLER_ORACLE_ID, "Hovel Hurler"),
        )
        .expect("Hovel Hurler clause must not be ambiguous")
        .expect("Hovel Hurler clause must match");
        assert_eq!(
            matched.id.as_str(),
            "ability.remove_counter.pump_flying.one"
        );
        let RecipeEmission::ActivatedAbility(ability) = matched.emission else {
            panic!("expected an activated ability, got {:?}", matched.emission);
        };
        assert_eq!(ability.source_zone, AbilitySourceZone::Battlefield);
        assert_eq!(
            ability.costs,
            vec![
                AbilityCost::Mana(ManaCost::parse("{R/W}{R/W}").expect("printed hybrid mana cost")),
                AbilityCost::RemoveCounters {
                    counter: None,
                    count: 1,
                    payment_source: CounterRemovalPaymentSource::Source,
                },
            ]
        );
        let another_creature_you_control = TargetFilter {
            kind: TargetKind::Creature,
            controller: TargetController::You,
            excluded_objects: vec![TargetObjectExclusion::Source],
            ..TargetFilter::default()
        };
        assert_eq!(
            ability.effect,
            vec![
                SpellEffectKind::PumpTarget {
                    power: 1,
                    toughness: 0,
                    scale: None,
                    subject: EffectSubject::Chosen(Box::new(another_creature_you_control.clone())),
                },
                SpellEffectKind::GrantKeywords {
                    subject: EffectSubject::Chosen(Box::new(another_creature_you_control)),
                    keywords: vec![Keyword::Flying],
                },
            ]
        );
        assert_eq!(ability.timing, ActivationTiming::SorcerySpeed);
        assert_eq!(
            ability.targeting,
            Some(exact_targeting(
                1,
                1,
                "Choose another target creature you control",
                vec![0, 1],
            ))
        );
    }

    #[test]
    fn issue_414_remove_two_counter_activations_match_their_exact_recipes() {
        // 1. Gnarlbark Elm: {2}{B} plus removing any two counters from the source pumps one target
        // creature -2/-2 until end of turn at sorcery speed. The two-counter cost is two atomic
        // any-one-counter components so a mixed-kind pair stays legal.
        let matched = match_clause(
            ISSUE_414_GNARLBARK_ELM_CLAUSE,
            false,
            &issue_414_context(ISSUE_414_GNARLBARK_ELM_ORACLE_ID, "Gnarlbark Elm"),
        )
        .expect("Gnarlbark Elm clause must not be ambiguous")
        .expect("Gnarlbark Elm clause must match");
        assert_eq!(
            matched.id.as_str(),
            "ability.remove_counter.pump_minus_two.two"
        );
        let RecipeEmission::ActivatedAbility(ability) = matched.emission else {
            panic!("expected an activated ability, got {:?}", matched.emission);
        };
        assert_eq!(ability.source_zone, AbilitySourceZone::Battlefield);
        assert_eq!(
            ability.costs,
            vec![
                AbilityCost::Mana(ManaCost::parse("{2}{B}").expect("printed mana cost")),
                AbilityCost::RemoveCounters {
                    counter: None,
                    count: 1,
                    payment_source: CounterRemovalPaymentSource::Source,
                },
                AbilityCost::RemoveCounters {
                    counter: None,
                    count: 1,
                    payment_source: CounterRemovalPaymentSource::Source,
                },
            ]
        );
        assert_eq!(
            ability.effect,
            vec![SpellEffectKind::PumpTarget {
                power: -2,
                toughness: -2,
                scale: None,
                subject: EffectSubject::Chosen(Box::new(TargetFilter::default_creature())),
            }]
        );
        assert_eq!(ability.timing, ActivationTiming::SorcerySpeed);
        assert_eq!(
            ability.targeting,
            Some(exact_targeting(1, 1, "Choose target creature", vec![0]))
        );

        // 2. Reaping Willow: {1}{W/B} plus removing any two counters from the source returns one
        // target creature card with mana value 3 or less from the controller's own graveyard to
        // the battlefield at sorcery speed.
        let matched = match_clause(
            ISSUE_414_REAPING_WILLOW_CLAUSE,
            false,
            &issue_414_context(ISSUE_414_REAPING_WILLOW_ORACLE_ID, "Reaping Willow"),
        )
        .expect("Reaping Willow clause must not be ambiguous")
        .expect("Reaping Willow clause must match");
        assert_eq!(
            matched.id.as_str(),
            "ability.remove_counter.return_creature_card.mana_value_three.two"
        );
        let RecipeEmission::ActivatedAbility(ability) = matched.emission else {
            panic!("expected an activated ability, got {:?}", matched.emission);
        };
        assert_eq!(ability.source_zone, AbilitySourceZone::Battlefield);
        assert_eq!(
            ability.costs,
            vec![
                AbilityCost::Mana(ManaCost::parse("{1}{W/B}").expect("printed hybrid mana cost")),
                AbilityCost::RemoveCounters {
                    counter: None,
                    count: 1,
                    payment_source: CounterRemovalPaymentSource::Source,
                },
                AbilityCost::RemoveCounters {
                    counter: None,
                    count: 1,
                    payment_source: CounterRemovalPaymentSource::Source,
                },
            ]
        );
        assert_eq!(
            ability.effect,
            vec![SpellEffectKind::MoveGraveyardCards {
                filter: GraveyardFilter {
                    owner: GraveyardOwner::Controller,
                    card: Some(ZoneCardFilter {
                        card_type: Some(CardTypeFilter::Creature),
                        max_mana_value: Some(3),
                        ..ZoneCardFilter::default()
                    }),
                    ..GraveyardFilter::default()
                },
                destination: GraveyardDestination::Battlefield { tapped: false },
                linked_exile_id: None,
            }]
        );
        assert_eq!(ability.timing, ActivationTiming::SorcerySpeed);
        assert_eq!(
            ability.targeting,
            Some(exact_targeting(
                1,
                1,
                "Choose target creature card with mana value 3 or less from your graveyard",
                vec![0],
            ))
        );
    }

