    #[test]
    fn issue_417_near_misses_stay_fail_closed() {
        for (clause, source, expected_owner) in [
            (
                "{2}, {T}, Sacrifice this creature: You gain 2 life.",
                issue_417_creature_context(),
                "ability.sacrifice_self.gain_life.three",
            ),
            (
                "{2}, {T}, Sacrifice this creature: You gain 3 life and draw a card.",
                issue_417_creature_context(),
                "ability.sacrifice_self.gain_life.three",
            ),
            (
                "{3}, {T}, Sacrifice this artifact: Draw two cards.",
                issue_417_artifact_context(),
                "ability.sacrifice_self.artifact.draw_two",
            ),
            (
                "{2}, {T}, Sacrifice this artifact: Draw a card.",
                issue_417_artifact_context(),
                "ability.sacrifice_self.artifact.draw_two",
            ),
            (
                "{2}, {T}, Pay 2 life: Tap target nonland permanent.",
                issue_417_artifact_context(),
                "ability.pay_life.tap_nonland",
            ),
            (
                "{2}, {T}, Pay 1 life: Tap target permanent.",
                issue_417_artifact_context(),
                "ability.pay_life.tap_nonland",
            ),
            (
                "{2}, {T}, Pay 1 life: Tap target nonland permanent. Draw a card.",
                issue_417_artifact_context(),
                "ability.pay_life.tap_nonland",
            ),
            (
                "{2}: This creature can't be blocked this turn except by creatures with haste.",
                issue_417_creature_context(),
                "ability.cant_be_blocked.self_except_haste",
            ),
            (
                "{1}: This creature can't be blocked this turn except by creatures with flying.",
                issue_417_creature_context(),
                "ability.cant_be_blocked.self_except_haste",
            ),
            (
                "{1}, {T}: This creature can't be blocked this turn except by creatures with haste.",
                issue_417_creature_context(),
                "ability.cant_be_blocked.self_except_haste",
            ),
            (
                "{2}, Sacrifice another creature: Draw a card. Activate only as a sorcery.",
                issue_417_creature_context(),
                "ability.sacrifice_another_creature_or_token.draw_one.sorcery",
            ),
            (
                "{2}, Sacrifice another creature or token: Draw a card.",
                issue_417_creature_context(),
                "ability.sacrifice_another_creature_or_token.draw_one.sorcery",
            ),
            (
                "{2}, Sacrifice another creature or artifact: Draw a card. Activate only as a sorcery.",
                issue_417_creature_context(),
                "ability.sacrifice_another_creature_or_token.draw_one.sorcery",
            ),
            (
                "{2}{G}: Until end of turn, target artifact you control becomes a 4/4 artifact creature.",
                issue_417_creature_context(),
                "ability.animate.noncreature_artifact.four_four",
            ),
            (
                "{2}{G}: Until end of turn, target noncreature artifact you control becomes a 4/4 creature.",
                issue_417_creature_context(),
                "ability.animate.noncreature_artifact.four_four",
            ),
            (
                "{2}{G}: Until end of turn, target noncreature artifact you control becomes a 5/5 artifact creature.",
                issue_417_creature_context(),
                "ability.animate.noncreature_artifact.four_four",
            ),
        ] {
            assert!(
                match_clause(clause, false, &source)
                    .unwrap_or_else(|ambiguity| panic!("{clause}: {ambiguity}"))
                    .map(|matched| matched.id.as_str())
                    != Some(expected_owner),
                "near-miss was accepted by {expected_owner}: {clause}"
            );
        }
    }

    fn issue_423_context(oracle_id: &str, name: &str) -> RecipeContext {
        let mut context = context();
        context.oracle_id = Some(oracle_id.into());
        context.source_name = name.into();
        context
    }

    fn issue_423_station_pair(threshold: u32, keyword_line: &str) -> String {
        format!(
            "Station (Tap another creature you control: Put charge counters equal to its power on this Spacecraft. Station only as a sorcery. It's an artifact creature at {threshold}+.)\n{threshold}+ | {keyword_line}"
        )
    }

    fn issue_423_station_activation(assembly: &StationAssemblyEmission) -> &ActivatedAbilityDef {
        &assembly.activated_ability
    }

    fn issue_423_only_static_definition(matched: &RecipeMatch) -> &StaticAbilityDef {
        let RecipeEmission::StaticAbility(ability) = &matched.emission else {
            panic!("issue #423 striation must emit exactly one static ability");
        };
        assert_eq!(ability.ability_id.as_str(), "static_01");
        &ability.definition
    }

    #[test]
    fn issue_423_spacecraft_station_assembly_is_exact_and_typed() {
        let greenhouse = issue_423_context(
            ISSUE_423_ATMOSPHERIC_GREENHOUSE_ORACLE_ID,
            "Atmospheric Greenhouse",
        );
        let pair = issue_423_station_pair(8, "Flying, trample");
        let matched = match_station_assembly(&pair, &greenhouse)
            .expect("Issue #423 Station pair must not be ambiguous")
            .expect("reviewed Station pair should match");
        assert_eq!(matched.id.as_str(), "station.spacecraft.thresholds");
        let RecipeEmission::StationAssembly(assembly) = matched.emission else {
            panic!("Station pair must emit the paired activated and static abilities")
        };
        let activation = issue_423_station_activation(&assembly);
        assert_eq!(
            activation.costs,
            [AbilityCost::TapPermanents {
                constraint: ObjectPaymentConstraint::ExactCount(1),
                filter: TargetFilter {
                    kind: TargetKind::Creature,
                    controller: TargetController::You,
                    ..TargetFilter::default()
                },
                exclude_source: true,
            }]
        );
        assert_eq!(activation.timing, ActivationTiming::SorcerySpeed);
        assert_eq!(
            activation.effect,
            [SpellEffectKind::PutCounters {
                counter: CounterKind::Charge,
                count: Amount::Count(CountExpression::CardResultCharacteristicSum {
                    filter: CardResultFilter {
                        source: CardResultSource::Payment,
                        action: CardResultAction::Tap,
                        players: RelativePlayerSet::Controller,
                        card_type: Some(CardTypeFilter::Creature),
                    },
                    characteristic: PowerToughnessCharacteristic::Power,
                }),
                subject: EffectSubject::Source,
            }]
        );
        assert_eq!(
            assembly.static_ability.definition,
            StaticAbilityDef::ConditionalSelfModifier {
                condition: GameCondition::SourceCounterCount {
                    counter: CounterKind::Charge,
                    min: Some(8),
                    max: None,
                },
                set_types: None,
                add_types: TypeLineAddition {
                    card_types: vec![PermanentTypeFilter::Creature],
                    creature_types: Vec::new(),
                },
                base_power: Some(5),
                base_toughness: Some(4),
                delta_power: 0,
                delta_toughness: 0,
                keywords: vec![Keyword::Flying, Keyword::Trample],
                activated_abilities: Vec::new(),
                triggered_abilities: Vec::new(),
                can_attack_as_though_without_defender: false,
            }
        );

        let dawnsire = issue_423_context(
            ISSUE_423_DAWNSIRE_ORACLE_ID,
            "Dawnsire, Sunstar Dreadnought",
        );
        let dawnsire_pair = issue_423_station_pair(20, "Flying");
        let matched = match_station_assembly(&dawnsire_pair, &dawnsire)
            .expect("Dawnsire pair must not be ambiguous")
            .expect("Dawnsire's 20+ keyword striation should match");
        let RecipeEmission::StationAssembly(assembly) = matched.emission else {
            panic!("Dawnsire pair must emit the paired abilities")
        };
        assert_eq!(
            assembly.static_ability.definition,
            StaticAbilityDef::ConditionalSelfModifier {
                condition: GameCondition::SourceCounterCount {
                    counter: CounterKind::Charge,
                    min: Some(20),
                    max: None,
                },
                set_types: None,
                add_types: TypeLineAddition {
                    card_types: vec![PermanentTypeFilter::Creature],
                    creature_types: Vec::new(),
                },
                base_power: Some(20),
                base_toughness: Some(20),
                delta_power: 0,
                delta_toughness: 0,
                keywords: vec![Keyword::Flying],
                activated_abilities: Vec::new(),
                triggered_abilities: Vec::new(),
                can_attack_as_though_without_defender: false,
            }
        );

        for near_miss in [
            issue_423_station_pair(9, "Flying, trample"),
            issue_423_station_pair(8, "Flying"),
            issue_423_station_pair(8, "Trample, flying"),
            issue_423_station_pair(8, "Flying, deathtouch"),
            format!("{pair}\n8+ | Flying, trample"),
            "Station (Tap another creature you control: Put charge counters equal to its power on this Planet. Station only as a sorcery.)\n8+ | Flying, trample".to_string(),
            issue_423_station_pair(8, "Flying, trample").replace(" at 8+.)", ".)"),
        ] {
            assert_eq!(
                match_station_assembly(&near_miss, &greenhouse),
                Ok(None),
                "unreviewed Station near-miss must stay unsupported: {near_miss}"
            );
        }
        let mut unreviewed = greenhouse.clone();
        unreviewed.oracle_id = Some("00000000-0000-0000-0000-000000000000".into());
        assert_eq!(match_station_assembly(&pair, &unreviewed), Ok(None));

        let mut excluded = greenhouse.clone();
        excluded.oracle_id = Some("90c5ea2b-d004-4219-b60c-d51bc1a5ee6b".into());
        excluded.source_name = "Entropic Battlecruiser".into();
        assert_eq!(
            match_station_assembly(&issue_423_station_pair(8, "Flying, deathtouch"), &excluded),
            Ok(None),
            "an excluded cohort identity must not match the generic keyword striation"
        );
    }

    #[test]
    fn issue_423_spacecraft_station_variants_cover_every_reviewed_striation() {
        for (oracle_id, name, threshold, keyword_line) in [
            (
                ISSUE_423_ATMOSPHERIC_GREENHOUSE_ORACLE_ID,
                "Atmospheric Greenhouse",
                8,
                "Flying, trample",
            ),
            (
                ISSUE_423_DAWNSIRE_ORACLE_ID,
                "Dawnsire, Sunstar Dreadnought",
                20,
                "Flying",
            ),
            (
                ISSUE_423_LARVAL_SCOUTLANDER_ORACLE_ID,
                "Larval Scoutlander",
                7,
                "Flying",
            ),
            (
                ISSUE_423_LUMEN_CLASS_FRIGATE_ORACLE_ID,
                "Lumen-Class Frigate",
                12,
                "Flying, lifelink",
            ),
            (
                ISSUE_423_SLEDGE_CLASS_SEEDSHIP_ORACLE_ID,
                "Sledge-Class Seedship",
                7,
                "Flying",
            ),
            (
                ISSUE_423_SPECIMEN_FREIGHTER_ORACLE_ID,
                "Specimen Freighter",
                9,
                "Flying",
            ),
            (
                ISSUE_423_SYNTHESIZER_LABSHIP_ORACLE_ID,
                "Synthesizer Labship",
                9,
                "Flying, vigilance",
            ),
        ] {
            let context = issue_423_context(oracle_id, name);
            let pair = issue_423_station_pair(threshold, keyword_line);
            let matched = match_station_assembly(&pair, &context)
                .unwrap_or_else(|ambiguity| panic!("{name}: {ambiguity}"))
                .unwrap_or_else(|| panic!("{name} must match its reviewed striation"));
            assert_eq!(
                matched.id.as_str(),
                "station.spacecraft.thresholds",
                "{name}"
            );
        }
    }

    #[test]
    fn issue_423_planet_station_assembly_grants_the_threshold_activation() {
        let kavaron = issue_423_context(ISSUE_423_KAVARON_ORACLE_ID, "Kavaron, Memorial World");
        let pair = format!("{ISSUE_423_PLANET_STATION_HEADER}\n{ISSUE_423_KAVARON_STRIATION}");
        let matched = match_station_assembly(&pair, &kavaron)
            .expect("Kavaron pair must not be ambiguous")
            .expect("Kavaron's reviewed pair should match");
        assert_eq!(matched.id.as_str(), "station.planets.12.activated");
        let RecipeEmission::StationAssembly(assembly) = matched.emission else {
            panic!("Planet pair must emit the paired abilities")
        };
        let StaticAbilityDef::ConditionalSelfModifier {
            condition,
            activated_abilities,
            triggered_abilities,
            ..
        } = assembly.static_ability.definition
        else {
            panic!("Planet threshold must be a conditional self modifier")
        };
        assert_eq!(
            condition,
            GameCondition::SourceCounterCount {
                counter: CounterKind::Charge,
                min: Some(12),
                max: None,
            }
        );
        assert!(triggered_abilities.is_empty());
        let [inner] = activated_abilities.as_slice() else {
            panic!("Kavaron's threshold grants exactly one activated ability")
        };
        assert_eq!(inner.timing, ActivationTiming::SorcerySpeed);
        assert_eq!(
            inner.costs,
            [
                fixed_mana_cost("{1}{R}"),
                AbilityCost::Tap,
                AbilityCost::SacrificePermanent {
                    filter: TargetFilter {
                        kind: TargetKind::AnyPermanent,
                        controller: TargetController::You,
                        permanent_types: vec![PermanentTypeFilter::Land],
                        ..TargetFilter::default()
                    },
                },
            ]
        );
        assert_eq!(
            inner.effect,
            [
                SpellEffectKind::CreateTokens {
                    token: "robot_c_2_2".into(),
                    count: Amount::Fixed(1),
                    who: PlayerRecipient::Controller,
                    tapped: false,
                    sacrifice_timing: None,
                },
                SpellEffectKind::PumpAll {
                    filter: CreatureScopeFilter {
                        controller: Some(CreatureScopeController::YouControl),
                        ..CreatureScopeFilter::default()
                    },
                    power: 1,
                    toughness: 0,
                },
                SpellEffectKind::GrantKeywordsAll {
                    filter: CreatureScopeFilter {
                        controller: Some(CreatureScopeController::YouControl),
                        ..CreatureScopeFilter::default()
                    },
                    keywords: vec![Keyword::Haste],
                },
            ]
        );

        let susur = issue_423_context(
            ISSUE_423_SUSUR_SECUNDI_ORACLE_ID,
            "Susur Secundi, Void Altar",
        );
        let susur_pair =
            format!("{ISSUE_423_PLANET_STATION_HEADER}\n{ISSUE_423_SUSUR_SECUNDI_STRIATION}");
        let matched = match_station_assembly(&susur_pair, &susur)
            .expect("Susur Secundi pair must not be ambiguous")
            .expect("Susur Secundi's reviewed pair should match");
        let RecipeEmission::StationAssembly(assembly) = matched.emission else {
            panic!("Susur Secundi pair must emit the paired abilities")
        };
        let StaticAbilityDef::ConditionalSelfModifier {
            activated_abilities,
            ..
        } = assembly.static_ability.definition
        else {
            panic!("Susur Secundi threshold must be a conditional self modifier")
        };
        let [inner] = activated_abilities.as_slice() else {
            panic!("Susur Secundi's threshold grants exactly one activated ability")
        };
        assert_eq!(
            inner.costs,
            [
                fixed_mana_cost("{1}{B}"),
                AbilityCost::Tap,
                AbilityCost::PayLife { amount: 2 },
                AbilityCost::SacrificePermanent {
                    filter: TargetFilter {
                        kind: TargetKind::Creature,
                        controller: TargetController::You,
                        ..TargetFilter::default()
                    },
                },
            ]
        );
        assert_eq!(
            inner.effect,
            [SpellEffectKind::Draw {
                who: PlayerRecipient::Controller,
                count: Amount::Count(CountExpression::CardResultCharacteristicSum {
                    filter: CardResultFilter {
                        source: CardResultSource::Payment,
                        action: CardResultAction::Sacrifice,
                        players: RelativePlayerSet::Controller,
                        card_type: Some(CardTypeFilter::Creature),
                    },
                    characteristic: PowerToughnessCharacteristic::Power,
                }),
            }]
        );

        for near_miss in [
            format!("{ISSUE_423_PLANET_STATION_HEADER}\n{}", ISSUE_423_KAVARON_STRIATION.replace("12+ |", "11+ |")),
            format!("{ISSUE_423_PLANET_STATION_HEADER}\n{}", ISSUE_423_KAVARON_STRIATION.replace("Sacrifice a land:", "Sacrifice a creature:")),
            format!("{ISSUE_423_PLANET_STATION_HEADER}\n{ISSUE_423_KAVARON_STRIATION}\n{ISSUE_423_KAVARON_STRIATION}"),
            format!("{ISSUE_423_KAVARON_STRIATION}\n{ISSUE_423_PLANET_STATION_HEADER}"),
            format!("{ISSUE_423_PLANET_STATION_HEADER}\n{ISSUE_423_SUSUR_SECUNDI_STRIATION}"),
        ] {
            assert_eq!(
                match_station_assembly(&near_miss, &kavaron),
                Ok(None),
                "reviewed Planet near-miss must stay unsupported: {near_miss}"
            );
        }
    }

    #[test]
    fn issue_423_threshold_statics_are_exact_and_typed() {
        let lumen = issue_423_context(
            ISSUE_423_LUMEN_CLASS_FRIGATE_ORACLE_ID,
            "Lumen-Class Frigate",
        );
        let matched = match_clause("2+ | Other creatures you control get +1/+1.", false, &lumen)
            .expect("Lumen anthem must not be ambiguous")
            .expect("Lumen's 2+ anthem should match");
        assert_eq!(
            matched.id.as_str(),
            "station.static.anthem.2.creatures_you_control"
        );
        assert_eq!(
            issue_423_only_static_definition(&matched),
            &StaticAbilityDef::AnthemPt {
                filter: CreatureScopeFilter {
                    controller: Some(CreatureScopeController::YouControl),
                    exclude_self: true,
                    ..CreatureScopeFilter::default()
                },
                condition: Some(GameCondition::SourceCounterCount {
                    counter: CounterKind::Charge,
                    min: Some(2),
                    max: None,
                }),
                delta_power: 1,
                delta_toughness: 1,
            }
        );

        let dawnsire = issue_423_context(
            ISSUE_423_DAWNSIRE_ORACLE_ID,
            "Dawnsire, Sunstar Dreadnought",
        );
        let clause = "10+ | Whenever you attack, Dawnsire deals 100 damage to up to one target creature or planeswalker.";
        let matched = match_clause(clause, false, &dawnsire)
            .expect("Dawnsire static must not be ambiguous")
            .expect("Dawnsire's 10+ attack trigger should match");
        assert_eq!(matched.id.as_str(), "station.static.damage.100.attack");
        let StaticAbilityDef::ConditionalSelfModifier {
            condition,
            triggered_abilities,
            ..
        } = issue_423_only_static_definition(&matched)
        else {
            panic!("Dawnsire's striation must be a conditional self modifier")
        };
        assert_eq!(
            condition,
            &GameCondition::SourceCounterCount {
                counter: CounterKind::Charge,
                min: Some(10),
                max: None,
            }
        );
        let [trigger] = triggered_abilities.as_slice() else {
            panic!("Dawnsire's striation grants exactly one triggered ability")
        };
        assert_eq!(
            trigger.trigger,
            TriggerCondition::WheneverControllerAttacks {
                min_attackers: None,
                max_attackers: None,
            }
        );
        assert_eq!(
            trigger.effect,
            [SpellEffectKind::DamageTarget {
                amount: Amount::Fixed(100),
                target: TargetFilter {
                    kind: TargetKind::AnyPermanent,
                    permanent_types: vec![
                        PermanentTypeFilter::Creature,
                        PermanentTypeFilter::Planeswalker,
                    ],
                    ..TargetFilter::default()
                },
            }]
        );
        assert_eq!(
            trigger.targeting,
            Some(exact_targeting(
                0,
                1,
                "Choose up to one target creature or planeswalker",
                vec![0],
            ))
        );

        let synthesizer = issue_423_context(
            ISSUE_423_SYNTHESIZER_LABSHIP_ORACLE_ID,
            "Synthesizer Labship",
        );
        let clause = "2+ | At the beginning of combat on your turn, up to one other target artifact you control becomes an artifact creature with base power and toughness 2/2 and gains flying until end of turn.";
        let matched = match_clause(clause, false, &synthesizer)
            .expect("Synthesizer static must not be ambiguous")
            .expect("Synthesizer's 2+ animation should match");
        assert_eq!(matched.id.as_str(), "station.static.combat_animation");
        let StaticAbilityDef::ConditionalSelfModifier {
            condition,
            triggered_abilities,
            ..
        } = issue_423_only_static_definition(&matched)
        else {
            panic!("Synthesizer's striation must be a conditional self modifier")
        };
        assert_eq!(
            condition,
            &GameCondition::SourceCounterCount {
                counter: CounterKind::Charge,
                min: Some(2),
                max: None,
            }
        );
        let [trigger] = triggered_abilities.as_slice() else {
            panic!("Synthesizer's striation grants exactly one triggered ability")
        };
        assert_eq!(
            trigger.trigger,
            TriggerCondition::AtBeginningOfCombat {
                player: CastTriggerPlayer::Controller,
            }
        );
        assert_eq!(trigger.effect.len(), 3);
        assert_eq!(
            trigger.targeting,
            Some(exact_targeting(
                0,
                1,
                "Choose up to one other target artifact you control",
                vec![0, 1, 2],
            ))
        );
        let SpellEffectKind::ApplyPermanentModifier {
            modifier: ResolvingPermanentModifier::SetBasePowerToughness { power, toughness },
            duration: ResolvingEffectDuration::UntilEndOfTurn,
            ..
        } = &trigger.effect[1]
        else {
            panic!("Synthesizer's second modifier sets base P/T until end of turn")
        };
        assert_eq!((*power, *toughness), (2, 2));

        for clause in [
            "2+ | Other creatures you control get +1/+1.",
            "10+ | Whenever you attack, Dawnsire deals 100 damage to up to one target creature or planeswalker.",
            "2+ | At the beginning of combat on your turn, up to one other target artifact you control becomes an artifact creature with base power and toughness 2/2 and gains flying until end of turn.",
        ] {
            let mut excluded = lumen.clone();
            excluded.oracle_id = Some("a6bcec1f-f515-4e63-9e84-8eb04cc582ff".into());
            excluded.source_name = "The Seriema".into();
            assert_eq!(
                match_clause(clause, false, &excluded),
                Ok(None),
                "an excluded identity must not inherit a reviewed striation: {clause}"
            );
        }
    }

    #[test]
    fn issue_423_companion_clauses_are_exact_and_typed() {
        let greenhouse = issue_423_context(
            ISSUE_423_ATMOSPHERIC_GREENHOUSE_ORACLE_ID,
            "Atmospheric Greenhouse",
        );
        let greenhouse_clause =
            "When this Spacecraft enters, put a +1/+1 counter on each creature you control.";
        let matched = match_clause(greenhouse_clause, false, &greenhouse)
            .expect("Greenhouse ETB must not be ambiguous")
            .expect("Greenhouse ETB should match");
        assert_eq!(matched.id.as_str(), "station.etb.counters_each_creature");
        assert_eq!(
            matched.emission,
            RecipeEmission::TriggeredAbility(TriggeredAbilityDef {
                ability_id: AbilityId::new("triggered_01").unwrap(),
                presentation: AbilityPresentation::OracleLines(vec![1]),
                trigger: TriggerCondition::WhenSelfEntersBattlefield,
                effect: vec![SpellEffectKind::PutCountersAll {
                    counter: CounterKind::PlusOnePlusOne,
                    count: Amount::Fixed(1),
                    filter: CreatureScopeFilter {
                        controller: Some(CreatureScopeController::YouControl),
                        ..CreatureScopeFilter::default()
                    },
                }],
                modal: None,
                targeting: None,
                may: false,
                intervening_if: None,
                max_triggers_per_turn: None,
                triggers_only_once: false,
            })
        );

        let larval =
            issue_423_context(ISSUE_423_LARVAL_SCOUTLANDER_ORACLE_ID, "Larval Scoutlander");
        let larval_clause = "When this Spacecraft enters, you may sacrifice a land or Lander. If you do, search your library for up to two basic land cards, put them onto the battlefield tapped, then shuffle.";
        let matched = match_clause(larval_clause, false, &larval)
            .expect("Larval ETB must not be ambiguous")
            .expect("Larval ETB should match");
        assert_eq!(matched.id.as_str(), "station.etb.sac_land_search_two");
        let RecipeEmission::TriggeredAbility(ability) = matched.emission else {
            panic!("Larval ETB must emit a triggered ability")
        };
        let [SpellEffectKind::ChooseResolutionBranch {
            optional, branches, ..
        }] = ability.effect.as_slice()
        else {
            panic!("Larval ETB must offer its printed optional branch")
        };
        assert!(optional);
        let [branch] = branches.as_slice() else {
            panic!("Larval ETB has exactly one printed branch")
        };
        assert_eq!(branch.branch_id.as_str(), "sacrifice_a_land_or_lander");
        assert_eq!(
            branch.cost,
            ResolutionCost::SacrificePermanent {
                filter: TargetFilter {
                    any_of: Some(vec![
                        TargetFilter {
                            kind: TargetKind::AnyPermanent,
                            controller: TargetController::You,
                            permanent_types: vec![PermanentTypeFilter::Land],
                            ..TargetFilter::default()
                        },
                        TargetFilter {
                            kind: TargetKind::AnyPermanent,
                            controller: TargetController::You,
                            required_subtypes: vec!["Lander".into()],
                            ..TargetFilter::default()
                        },
                    ]),
                    ..TargetFilter::default()
                },
                source_only: false,
            }
        );
        let [SpellEffectKind::SearchLibrary {
            count,
            filter,
            zones,
            destination,
            shuffle,
            optional,
            ..
        }] = branch.effects.as_slice()
        else {
            panic!("Larval's branch searches its library")
        };
        assert_eq!((*count, *optional, *shuffle), (2, false, true));
        assert_eq!(
            filter,
            &Some(ZoneCardFilter {
                card_type: Some(CardTypeFilter::BasicLand),
                ..ZoneCardFilter::default()
            })
        );
        assert_eq!(zones, &SearchZoneSelection::default());
        assert_eq!(
            destination,
            &SearchDestination::Battlefield { tapped: true }
        );

        let sledge = issue_423_context(
            ISSUE_423_SLEDGE_CLASS_SEEDSHIP_ORACLE_ID,
            "Sledge-Class Seedship",
        );
        let sledge_clause = "Whenever this Spacecraft attacks, you may put a creature card from your hand onto the battlefield.";
        let matched = match_clause(sledge_clause, false, &sledge)
            .expect("Sledge attack must not be ambiguous")
            .expect("Sledge attack should match");
        assert_eq!(matched.id.as_str(), "station.attack.put_creature_from_hand");
        let RecipeEmission::TriggeredAbility(ability) = matched.emission else {
            panic!("Sledge attack must emit a triggered ability")
        };
        assert_eq!(
            ability.trigger,
            TriggerCondition::WheneverSelfAttacks {
                minimum_other_attackers: 0,
            }
        );
        let [SpellEffectKind::SearchLibrary {
            optional,
            count,
            filter,
            zones,
            destination,
            shuffle,
            ..
        }] = ability.effect.as_slice()
        else {
            panic!("Sledge attack puts a hand card onto the battlefield")
        };
        assert_eq!((*optional, *count, *shuffle), (true, 1, false));
        assert_eq!(
            filter,
            &Some(ZoneCardFilter {
                card_type: Some(CardTypeFilter::Creature),
                ..ZoneCardFilter::default()
            })
        );
        assert_eq!(
            zones,
            &SearchZoneSelection::Fixed(vec![CardSearchZone::Hand])
        );
        assert_eq!(
            destination,
            &SearchDestination::Battlefield { tapped: false }
        );

        let specimen =
            issue_423_context(ISSUE_423_SPECIMEN_FREIGHTER_ORACLE_ID, "Specimen Freighter");
        let bounce_clause = "When this Spacecraft enters, return up to two target non-Spacecraft creatures to their owners' hands.";
        let matched = match_clause(bounce_clause, false, &specimen)
            .expect("Specimen ETB must not be ambiguous")
            .expect("Specimen ETB should match");
        assert_eq!(matched.id.as_str(), "station.etb.bounce_two_nonspacecraft");
        let RecipeEmission::TriggeredAbility(ability) = matched.emission else {
            panic!("Specimen ETB must emit a triggered ability")
        };
        assert_eq!(
            ability.targeting,
            Some(exact_targeting(
                0,
                2,
                "Choose up to two target non-Spacecraft creatures",
                vec![0],
            ))
        );
        assert_eq!(
            ability.effect,
            [SpellEffectKind::ReturnToOwnersHand {
                subject: EffectSubject::Chosen(Box::new(TargetFilter {
                    kind: TargetKind::Creature,
                    excluded_subtypes: vec!["Spacecraft".into()],
                    ..TargetFilter::default()
                })),
            }]
        );

        let mill_clause = "Whenever this Spacecraft attacks, defending player mills four cards.";
        let matched = match_clause(mill_clause, false, &specimen)
            .expect("Specimen attack must not be ambiguous")
            .expect("Specimen attack should match");
        assert_eq!(matched.id.as_str(), "station.attack.mill_four_defending");
        assert_eq!(
            matched.emission,
            RecipeEmission::TriggeredAbility(TriggeredAbilityDef {
                ability_id: AbilityId::new("triggered_01").unwrap(),
                presentation: AbilityPresentation::OracleLines(vec![1]),
                trigger: TriggerCondition::WheneverSelfAttacks {
                    minimum_other_attackers: 0,
                },
                effect: vec![SpellEffectKind::Mill {
                    count: Amount::Fixed(4),
                    who: PlayerRecipient::DefendingPlayer,
                }],
                modal: None,
                targeting: None,
                may: false,
                intervening_if: None,
                max_triggers_per_turn: None,
                triggers_only_once: false,
            })
        );
    }

    #[test]
    fn issue_423_reviewed_surfaces_and_unreviewed_identity_fail_closed() {
        assert!(issue_423_oracle_id_is_reviewed(
            ISSUE_423_ATMOSPHERIC_GREENHOUSE_ORACLE_ID
        ));
        assert!(!issue_423_oracle_id_is_reviewed(
            "70d35dbd-1d91-4a2a-a643-6870d168f4f5"
        ));
        assert!(issue_423_card_surface_is_exact(
            ISSUE_423_ATMOSPHERIC_GREENHOUSE_ORACLE_ID,
            "Atmospheric Greenhouse",
            "{4}{G}",
            "Artifact — Spacecraft",
            "When this Spacecraft enters, put a +1/+1 counter on each creature you control.\nStation (Tap another creature you control: Put charge counters equal to its power on this Spacecraft. Station only as a sorcery. It's an artifact creature at 8+.)\n8+ | Flying, trample",
            Some("5"),
            Some("4"),
        ));
        assert!(!issue_423_card_surface_is_exact(
            ISSUE_423_ATMOSPHERIC_GREENHOUSE_ORACLE_ID,
            "Atmospheric Greenhouse",
            "{4}{G}",
            "Artifact — Spacecraft",
            "When this Spacecraft enters, put a +1/+1 counter on each creature you control.\nStation (Tap another creature you control: Put charge counters equal to its power on this Spacecraft. Station only as a sorcery. It's an artifact creature at 9+.)\n9+ | Flying, trample",
            Some("5"),
            Some("4"),
        ));
        assert!(issue_423_card_surface_is_exact(
            "00000000-0000-0000-0000-000000000000",
            "Unknown",
            "",
            "",
            "",
            None,
            None,
        ));
        for oracle_id in ISSUE_423_REVIEWED_ORACLE_IDS {
            assert!(issue_423_oracle_id_is_reviewed(oracle_id));
        }
        assert_eq!(ISSUE_423_REVIEWED_ORACLE_IDS.len(), 9);
    }

    // -----------------------------------------------------------------------
    // Issue #426 — one-mode-away `Choose one —` modal identities.
    // -----------------------------------------------------------------------

    fn issue_426_context(source_name: &str) -> RecipeContext {
        let mut context = context();
        context.source_name = source_name.into();
        context
    }

    fn issue_426_modal_mode(
        source_name: &str,
        clause: &str,
        expected_id: &str,
    ) -> ModalModeEmission {
        let matched = match_modal_mode(clause, &issue_426_context(source_name))
            .unwrap_or_else(|error| panic!("{clause}: {error}"))
            .unwrap_or_else(|| panic!("missing modal_mode recipe for {clause}"));
        assert_eq!(matched.id.as_str(), expected_id, "{clause}");
        let RecipeEmission::ModalMode(emission) = matched.emission else {
            panic!("{expected_id} must emit a modal mode");
        };
        emission
    }

    const ISSUE_426_REVEAL_DISCARD_CLAUSE: &str =
        "Target opponent reveals their hand. You choose a nonland card from it. That player discards that card.";
    const ISSUE_426_COLLISION_COURSE_CLAUSE: &str =
        "Collision Course deals X damage to target creature, where X is the number of permanents you control that are creatures and/or Vehicles.";
    const ISSUE_426_CONFOUNDING_RIDDLE_CLAUSE: &str =
        "Look at the top four cards of your library. Put one of them into your hand and the rest into your graveyard.";
    const ISSUE_426_COORDINATED_MANEUVER_CLAUSE: &str =
        "Coordinated Maneuver deals damage equal to the number of creatures you control to target creature or planeswalker.";
    const ISSUE_426_CRASH_AND_BURN_CLAUSE: &str =
        "Crash and Burn deals 6 damage to target creature or planeswalker.";
    const ISSUE_426_FRONTLINE_RUSH_CLAUSE: &str =
        "Target creature gets +X/+X until end of turn, where X is the number of creatures you control.";
    const ISSUE_426_KEEP_OUT_CLAUSE: &str = "Keep Out deals 4 damage to target tapped creature.";
    const ISSUE_426_MOMENT_OF_VALOR_CLAUSE: &str =
        "Untap target creature. It gets +1/+0 and gains indestructible until end of turn.";
    const ISSUE_426_OVER_THE_EDGE_CLAUSE: &str = r#"Target creature you control explores, then it explores again. (Reveal the top card of your library. Put that card into your hand if it's a land. Otherwise, put a +1/+1 counter on that creature, then put the card back or put it into your graveyard. Then repeat this process.)"#;
    const ISSUE_426_SPECTACULAR_TACTICS_CLAUSE: &str =
        "Put a +1/+1 counter on target creature you control. It gains hexproof until end of turn.";
    const ISSUE_426_STONE_BY_SUNLIGHT_CLAUSE: &str = r#"Until end of turn, target creature becomes an artifact in addition to its other types and gains indestructible. (Damage and effects that say "destroy" don't destroy it.)"#;

    fn issue_426_creature_or_planeswalker() -> TargetFilter {
        TargetFilter {
            kind: TargetKind::AnyPermanent,
            permanent_types: vec![
                PermanentTypeFilter::Creature,
                PermanentTypeFilter::Planeswalker,
            ],
            ..TargetFilter::default()
        }
    }

    fn issue_426_creature_you_control() -> TargetFilter {
        TargetFilter {
            kind: TargetKind::Creature,
            controller: TargetController::You,
            ..TargetFilter::default()
        }
    }

    #[test]
    fn issue_426_modal_mode_recipes_match_their_exact_clauses() {
        for (source_name, clause, expected_id) in [
            (
                "Cerebral Confiscation",
                ISSUE_426_REVEAL_DISCARD_CLAUSE,
                "modal_mode.reveal_hand_choose_nonland_discard",
            ),
            (
                "Collision Course",
                ISSUE_426_COLLISION_COURSE_CLAUSE,
                "modal_mode.damage.creature.count_creatures_and_vehicles_you_control",
            ),
            (
                "Coordinated Maneuver",
                ISSUE_426_COORDINATED_MANEUVER_CLAUSE,
                "modal_mode.damage.creature_or_planeswalker.count_creatures_you_control",
            ),
            (
                "Crash and Burn",
                ISSUE_426_CRASH_AND_BURN_CLAUSE,
                "modal_mode.damage.creature_or_planeswalker.six.source",
            ),
            (
                "Frontline Rush",
                ISSUE_426_FRONTLINE_RUSH_CLAUSE,
                "modal_mode.pump.target.x_creatures_you_control",
            ),
            (
                "Keep Out",
                ISSUE_426_KEEP_OUT_CLAUSE,
                "modal_mode.damage.tapped_creature.four.source",
            ),
            (
                "Moment of Valor",
                ISSUE_426_MOMENT_OF_VALOR_CLAUSE,
                "modal_mode.untap.pump.plus_one_power.indestructible",
            ),
            (
                "Over the Edge",
                ISSUE_426_OVER_THE_EDGE_CLAUSE,
                "modal_mode.explore.target_controlled.twice",
            ),
            (
                "Spectacular Tactics",
                ISSUE_426_SPECTACULAR_TACTICS_CLAUSE,
                "modal_mode.put_counter.plus_one.hexproof",
            ),
            (
                "Stone by Sunlight",
                ISSUE_426_STONE_BY_SUNLIGHT_CLAUSE,
                "modal_mode.becomes_artifact.indestructible",
            ),
        ] {
            let matched = match_modal_mode(clause, &issue_426_context(source_name))
                .unwrap_or_else(|error| panic!("{clause}: {error}"))
                .unwrap_or_else(|| panic!("missing modal_mode recipe for {clause}"));
            assert_eq!(matched.id.as_str(), expected_id, "{clause}");
        }

        for recipe_id in [
            "modal_mode.reveal_hand_choose_nonland_discard",
            "modal_mode.damage.creature.count_creatures_and_vehicles_you_control",
            "modal_mode.damage.creature_or_planeswalker.count_creatures_you_control",
            "modal_mode.damage.creature_or_planeswalker.six.source",
            "modal_mode.pump.target.x_creatures_you_control",
            "modal_mode.damage.tapped_creature.four.source",
            "modal_mode.untap.pump.plus_one_power.indestructible",
            "modal_mode.explore.target_controlled.twice",
            "modal_mode.put_counter.plus_one.hexproof",
            "modal_mode.becomes_artifact.indestructible",
        ] {
            let recipe = CATALOG
                .iter()
                .find(|recipe| recipe.id.as_str() == recipe_id)
                .unwrap_or_else(|| panic!("missing issue #426 recipe {recipe_id}"));
            assert_eq!(recipe.surface, RecipeSurface::ModalMode, "{recipe_id}");
        }

        // Confounding Riddle stays unmapped: no shipped instruction puts one looked-at card into
        // hand and the remainder into the graveyard. `LibraryPartition` keeps its retained cohort
        // on top (`recipes.rs` matcher docs / `primitives/effects.rs:1031`), and
        // `LookChooseToHand` sends the remainder to the bottom (`effects.rs:1055`).
        assert!(
            match_modal_mode(
                ISSUE_426_CONFOUNDING_RIDDLE_CLAUSE,
                &issue_426_context("Confounding Riddle"),
            )
            .expect("the look-four mode must not be ambiguous")
            .is_none(),
            "Confounding Riddle's look-four mode has no shipped destination shape"
        );
    }

    #[test]
    fn issue_426_modal_mode_recipes_emit_typed_payloads() {
        assert_eq!(
            issue_426_modal_mode(
                "Cerebral Confiscation",
                ISSUE_426_REVEAL_DISCARD_CLAUSE,
                "modal_mode.reveal_hand_choose_nonland_discard",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::ChooseHandCards {
                    action: HandCardAction::Discard,
                    count: 1,
                    target: TargetFilter {
                        kind: TargetKind::OpponentPlayer,
                        ..TargetFilter::default()
                    },
                    chooser: HandCardChooser::Controller,
                    card_filter: Some(CardTypeFilter::Nonland),
                    optional: false,
                    visibility: HandChoiceVisibility::PublicReveal,
                }],
                targeting: modal_targeting("Choose target opponent", 0),
            }
        );

        let creature = BattlefieldPermanentFilter {
            token: None,
            any_of: None,
            controllers: RelativePlayerSet::Controller,
            card_type: Some(CardTypeFilter::Creature),
            color: None,
            name: None,
            required_subtypes: Vec::new(),
            exclude_source: false,
        };
        let vehicle = BattlefieldPermanentFilter {
            token: None,
            any_of: None,
            controllers: RelativePlayerSet::Controller,
            card_type: None,
            color: None,
            name: None,
            required_subtypes: vec!["Vehicle".into()],
            exclude_source: false,
        };
        assert_eq!(
            issue_426_modal_mode(
                "Collision Course",
                ISSUE_426_COLLISION_COURSE_CLAUSE,
                "modal_mode.damage.creature.count_creatures_and_vehicles_you_control",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::DamageTarget {
                    amount: Amount::Count(CountExpression::BattlefieldPermanents {
                        filter: BattlefieldPermanentFilter {
                            token: None,
                            any_of: Some(vec![creature, vehicle]),
                            controllers: RelativePlayerSet::Controller,
                            card_type: None,
                            color: None,
                            name: None,
                            required_subtypes: Vec::new(),
                            exclude_source: false,
                        },
                    }),
                    target: TargetFilter::default_creature(),
                }],
                targeting: modal_targeting("Choose target creature", 0),
            }
        );

        assert_eq!(
            issue_426_modal_mode(
                "Coordinated Maneuver",
                ISSUE_426_COORDINATED_MANEUVER_CLAUSE,
                "modal_mode.damage.creature_or_planeswalker.count_creatures_you_control",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::DamageTarget {
                    amount: Amount::Count(CountExpression::BattlefieldCreatures {
                        filter: BattlefieldCreatureCountFilter::default(),
                    }),
                    target: issue_426_creature_or_planeswalker(),
                }],
                targeting: modal_targeting("Choose target creature or planeswalker", 0),
            }
        );

        assert_eq!(
            issue_426_modal_mode(
                "Crash and Burn",
                ISSUE_426_CRASH_AND_BURN_CLAUSE,
                "modal_mode.damage.creature_or_planeswalker.six.source",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::DamageTarget {
                    amount: Amount::Fixed(6),
                    target: issue_426_creature_or_planeswalker(),
                }],
                targeting: modal_targeting("Choose target creature or planeswalker", 0),
            }
        );

        assert_eq!(
            issue_426_modal_mode(
                "Frontline Rush",
                ISSUE_426_FRONTLINE_RUSH_CLAUSE,
                "modal_mode.pump.target.x_creatures_you_control",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::PumpTarget {
                    power: 0,
                    toughness: 0,
                    scale: Some(PtScale {
                        basis: PtScaleBasis::Amount(Amount::Count(
                            CountExpression::BattlefieldCreatures {
                                filter: BattlefieldCreatureCountFilter::default(),
                            },
                        )),
                        power_per_unit: 1,
                        toughness_per_unit: 1,
                    }),
                    subject: EffectSubject::Chosen(Box::new(TargetFilter::default_creature())),
                }],
                targeting: modal_targeting("Choose target creature", 0),
            }
        );

        assert_eq!(
            issue_426_modal_mode(
                "Keep Out",
                ISSUE_426_KEEP_OUT_CLAUSE,
                "modal_mode.damage.tapped_creature.four.source",
            ),
            ModalModeEmission {
                effects: vec![SpellEffectKind::DamageTarget {
                    amount: Amount::Fixed(4),
                    target: TargetFilter {
                        kind: TargetKind::Creature,
                        tapped: Some(true),
                        ..TargetFilter::default()
                    },
                }],
                targeting: modal_targeting("Choose target tapped creature", 0),
            }
        );

        let moment_target = TargetFilter::default_creature();
        assert_eq!(
            issue_426_modal_mode(
                "Moment of Valor",
                ISSUE_426_MOMENT_OF_VALOR_CLAUSE,
                "modal_mode.untap.pump.plus_one_power.indestructible",
            ),
            ModalModeEmission {
                effects: vec![
                    SpellEffectKind::Untap {
                        subject: EffectSubject::Chosen(Box::new(moment_target.clone())),
                    },
                    SpellEffectKind::PumpTarget {
                        power: 1,
                        toughness: 0,
                        scale: None,
                        subject: EffectSubject::Chosen(Box::new(moment_target.clone())),
                    },
                    SpellEffectKind::GrantKeywords {
                        subject: EffectSubject::Chosen(Box::new(moment_target)),
                        keywords: vec![Keyword::Indestructible],
                    },
                ],
                targeting: modal_targeting_groups(vec![("Choose target creature", vec![0, 1, 2])]),
            }
        );

        let explore_target = issue_426_creature_you_control();
        assert_eq!(
            issue_426_modal_mode(
                "Over the Edge",
                ISSUE_426_OVER_THE_EDGE_CLAUSE,
                "modal_mode.explore.target_controlled.twice",
            ),
            ModalModeEmission {
                effects: vec![
                    SpellEffectKind::Explore {
                        subject: EffectSubject::Chosen(Box::new(explore_target.clone())),
                    },
                    SpellEffectKind::Explore {
                        subject: EffectSubject::Chosen(Box::new(explore_target)),
                    },
                ],
                targeting: modal_targeting_groups(vec![(
                    "Choose target creature you control",
                    vec![0, 1]
                )]),
            }
        );

        let counter_target = issue_426_creature_you_control();
        assert_eq!(
            issue_426_modal_mode(
                "Spectacular Tactics",
                ISSUE_426_SPECTACULAR_TACTICS_CLAUSE,
                "modal_mode.put_counter.plus_one.hexproof",
            ),
            ModalModeEmission {
                effects: vec![
                    SpellEffectKind::PutCounters {
                        counter: CounterKind::PlusOnePlusOne,
                        count: Amount::Fixed(1),
                        subject: EffectSubject::Chosen(Box::new(counter_target.clone())),
                    },
                    SpellEffectKind::GrantKeywords {
                        subject: EffectSubject::Chosen(Box::new(counter_target)),
                        keywords: vec![Keyword::Hexproof],
                    },
                ],
                targeting: modal_targeting_groups(vec![(
                    "Choose target creature you control",
                    vec![0, 1]
                )]),
            }
        );

        let artifact_target = TargetFilter::default_creature();
        assert_eq!(
            issue_426_modal_mode(
                "Stone by Sunlight",
                ISSUE_426_STONE_BY_SUNLIGHT_CLAUSE,
                "modal_mode.becomes_artifact.indestructible",
            ),
            ModalModeEmission {
                effects: vec![
                    SpellEffectKind::AddTypes {
                        subject: EffectSubject::Chosen(Box::new(artifact_target.clone())),
                        addition: TypeLineAddition {
                            card_types: vec![PermanentTypeFilter::Artifact],
                            creature_types: Vec::new(),
                        },
                    },
                    SpellEffectKind::GrantKeywords {
                        subject: EffectSubject::Chosen(Box::new(artifact_target)),
                        keywords: vec![Keyword::Indestructible],
                    },
                ],
                targeting: modal_targeting_groups(vec![("Choose target creature", vec![0, 1])]),
            }
        );
    }

    #[test]
    fn issue_426_modal_mode_recipes_reject_near_misses() {
        for (source_name, clause) in [
            // Scope and count swaps on the reveal/discard mode.
            (
                "Cerebral Confiscation",
                "Target player reveals their hand. You choose a nonland card from it. That player discards that card.",
            ),
            (
                "Cerebral Confiscation",
                "Target opponent reveals their hand. You choose a card from it. That player discards that card.",
            ),
            (
                "Cerebral Confiscation",
                "Target opponent reveals their hand. You choose a nonland card from it. That player exiles that card.",
            ),
            (
                "Cerebral Confiscation",
                "Target opponent reveals their hand. You choose two nonland cards from it. That player discards those cards.",
            ),
            (
                "Cerebral Confiscation",
                "Target opponent reveals their hand. You may choose a nonland card from it. That player discards that card.",
            ),
            (
                "Cerebral Confiscation",
                "Target opponent reveals their hand. You choose a nonland card from it. That player discards that card. Draw a card.",
            ),
            // Another count or receipt on the creature/Vehicle count damage.
            (
                "Collision Course",
                "Collision Course deals X damage to target creature, where X is the number of permanents you control that are creatures or Vehicles.",
            ),
            (
                "Collision Course",
                "Collision Course deals X damage to target creature, where X is the number of creatures you control.",
            ),
            (
                "Collision Course",
                "Collision Course deals X damage to target creature, where X is the number of permanents you control that are artifacts and/or Vehicles.",
            ),
            (
                "Collision Course",
                "Collision Course deals X damage to target creature, where X is the number of permanents you control that are creatures and/or Vehicles. Draw a card.",
            ),
            // Amount and target swaps on the count-based damage.
            (
                "Coordinated Maneuver",
                "Coordinated Maneuver deals damage equal to the number of creatures you control to target creature.",
            ),
            (
                "Coordinated Maneuver",
                "Coordinated Maneuver deals damage equal to the number of creatures you control to target creature an opponent controls.",
            ),
            (
                "Coordinated Maneuver",
                "Coordinated Maneuver deals damage equal to the number of creatures your opponents control to target creature or planeswalker.",
            ),
            (
                "Coordinated Maneuver",
                "Coordinated Maneuver deals 3 damage to target creature or planeswalker.",
            ),
            // Another amount or a creature-only target on the six-damage mode.
            (
                "Crash and Burn",
                "Crash and Burn deals 5 damage to target creature or planeswalker.",
            ),
            (
                "Crash and Burn",
                "Crash and Burn deals 6 damage to target creature.",
            ),
            (
                "Crash and Burn",
                "Crash and Burn deals 6 damage to any target.",
            ),
            (
                "Crash and Burn",
                "Crash and Burn deals 6 damage to target creature or planeswalker. Draw a card.",
            ),
            // Another quantity, scope, or target form on the X pump.
            (
                "Frontline Rush",
                "Target creature gets +X/+X until end of turn, where X is the number of creatures your opponents control.",
            ),
            (
                "Frontline Rush",
                "Target creature you control gets +X/+X until end of turn, where X is the number of creatures you control.",
            ),
            (
                "Frontline Rush",
                "Target creature gets +X/+0 until end of turn, where X is the number of creatures you control.",
            ),
            (
                "Frontline Rush",
                "Up to one target creature gets +X/+X until end of turn, where X is the number of creatures you control.",
            ),
            (
                "Frontline Rush",
                "Target creature gets +X/+X until end of turn, where X is the number of artifacts you control.",
            ),
            // Another amount or tapped scope on the tapped-creature damage.
            (
                "Keep Out",
                "Keep Out deals 3 damage to target tapped creature.",
            ),
            (
                "Keep Out",
                "Keep Out deals 4 damage to target untapped creature.",
            ),
            (
                "Keep Out",
                "Keep Out deals 4 damage to target tapped creature you control.",
            ),
            (
                "Keep Out",
                "Keep Out deals 4 damage to target tapped creature. Draw a card.",
            ),
            // Clause splits, ordering, and keyword swaps on the untap mode.
            (
                "Moment of Valor",
                "Untap target creature. It gets +1/+1 and gains indestructible until end of turn.",
            ),
            (
                "Moment of Valor",
                "Untap target creature you control. It gets +1/+0 and gains indestructible until end of turn.",
            ),
            (
                "Moment of Valor",
                "Untap target creature. It gets +1/+0 and gains hexproof until end of turn.",
            ),
            (
                "Moment of Valor",
                "Untap target creature. It gets +1/+0 until end of turn and gains indestructible.",
            ),
            (
                "Moment of Valor",
                "Untap target creature. It gains indestructible until end of turn, then it gets +1/+0 until end of turn.",
            ),
            (
                "Moment of Valor",
                "Tap target creature. It gets +1/+0 and gains indestructible until end of turn.",
            ),
            // Printed reminder is part of the explore mode contract.
            (
                "Over the Edge",
                "Target creature you control explores, then it explores again.",
            ),
            (
                "Over the Edge",
                "Target creature you control explores twice.",
            ),
            (
                "Over the Edge",
                "Target creature explores, then it explores again. (Reveal the top card of your library. Put that card into your hand if it's a land. Otherwise, put a +1/+1 counter on that creature, then put the card back or put it into your graveyard. Then repeat this process.)",
            ),
            (
                "Over the Edge",
                "Target creature you control explores, then it explores again. (Reveal the top card of your library.)",
            ),
            (
                "Over the Edge",
                "Target creature you control explores, then it explores again. Draw a card.",
            ),
            // Reminder text added where the modal bullet does not print it.
            (
                "Spectacular Tactics",
                "Put a +1/+1 counter on target creature you control. It gains hexproof until end of turn. (It can't be the target of spells or abilities your opponents control.)",
            ),
            (
                "Spectacular Tactics",
                "Put a +1/+1 counter on target creature you control. It gains hexproof until end of turn. Draw a card.",
            ),
            (
                "Spectacular Tactics",
                "Put a +1/+1 counter on target creature. It gains hexproof until end of turn.",
            ),
            (
                "Spectacular Tactics",
                "Put a +1/+1 counter on up to one target creature you control. It gains hexproof until end of turn.",
            ),
            (
                "Spectacular Tactics",
                "Put two +1/+1 counters on target creature you control. It gains hexproof until end of turn.",
            ),
            // The trample-and-hexproof form keeps its shipped owner instead of collapsing into
            // the new hexproof-only recipe; that cross-owner route is asserted below.
            // Type-addition contract: artifact creature and reminder forms stay exact.
            (
                "Stone by Sunlight",
                "Until end of turn, target creature becomes an artifact creature in addition to its other types and gains indestructible. (Damage and effects that say \"destroy\" don't destroy it.)",
            ),
            (
                "Stone by Sunlight",
                "Until end of turn, target creature becomes an artifact in addition to its other types and gains indestructible.",
            ),
            (
                "Stone by Sunlight",
                "Until end of turn, target creature becomes an artifact in addition to its other types and gains hexproof. (Damage and effects that say \"destroy\" don't destroy it.)",
            ),
            (
                "Stone by Sunlight",
                "Target creature becomes an artifact in addition to its other types and gains indestructible. (Damage and effects that say \"destroy\" don't destroy it.)",
            ),
            (
                "Stone by Sunlight",
                "Until end of turn, target creature you control becomes an artifact in addition to its other types and gains indestructible. (Damage and effects that say \"destroy\" don't destroy it.)",
            ),
            (
                "Stone by Sunlight",
                "Until end of turn, target creature becomes an artifact in addition to its other types and gains indestructible. (Damage and effects that say \"destroy\" don't destroy it. If its toughness is 0 or less, it still dies.)",
            ),
        ] {
            assert!(
                match_modal_mode(clause, &issue_426_context(source_name))
                    .unwrap_or_else(|ambiguity| panic!("{clause}: {ambiguity}"))
                    .is_none(),
                "{source_name} near-miss was accepted: {clause}"
            );
        }

        // Cross-owner checks: the shipped non-modal reveal/discard clause keeps its own surface,
        // and the existing four-damage creature and two-damage tapped-creature modes keep owning
        // their own forms.
        assert_eq!(
            match_modal_mode(
                "Reroute Systems deals 2 damage to target tapped creature.",
                &issue_426_context("Reroute Systems"),
            )
            .expect("the two-damage mode must not be ambiguous")
            .expect("the shipped tapped-creature mode should match")
            .id
            .as_str(),
            "modal_mode.damage.tapped_creature.two.source"
        );
        assert_eq!(
            match_modal_mode(
                "Keep Out deals 4 damage to target creature.",
                &issue_426_context("Keep Out"),
            )
            .expect("the four-damage creature mode must not be ambiguous")
            .expect("the shipped creature-damage mode keeps its owner")
            .id
            .as_str(),
            "modal_mode.damage.creature.four.source"
        );
        assert_eq!(
            match_modal_mode(
                "Put a +1/+1 counter on target creature you control. It gains trample and hexproof until end of turn.",
                &issue_426_context("Warg Tactics"),
            )
            .expect("the trample-and-hexproof mode must not be ambiguous")
            .expect("the shipped trample-and-hexproof mode keeps its owner")
            .id
            .as_str(),
            "modal_mode.put_counter.creature.plus_one_plus_one.trample_hexproof"
        );
        assert_eq!(
            match_modal_mode("Destroy target enchantment.", &context())
                .expect("the enchantment mode must not be ambiguous")
                .expect("the shipped enchantment mode should match")
                .id
                .as_str(),
            "modal_mode.destroy.enchantment"
        );
    }

    #[test]
    fn issue_426_reviewed_modal_mode_sets_bind_exactly() {
        for (ids, bounds) in [
            (
                &[
                    "modal_mode.discard.target_opponent.two",
                    "modal_mode.reveal_hand_choose_nonland_discard",
                ][..],
                (1u32, 1u32),
            ),
            (
                &[
                    "modal_mode.damage.creature.count_creatures_and_vehicles_you_control",
                    "modal_mode.destroy.artifact",
                ][..],
                (1, 1),
            ),
            (
                &[
                    "modal_mode.damage.creature_or_planeswalker.count_creatures_you_control",
                    "modal_mode.destroy.enchantment",
                ][..],
                (1, 1),
            ),
            (
                &[
                    "modal_mode.destroy.vehicle",
                    "modal_mode.damage.creature_or_planeswalker.six.source",
                ][..],
                (1, 1),
            ),
            (
                &[
                    "modal_mode.create_tokens.goblin_red_one_one.two",
                    "modal_mode.pump.target.x_creatures_you_control",
                ][..],
                (1, 1),
            ),
            (
                &[
                    "modal_mode.damage.tapped_creature.four.source",
                    "modal_mode.destroy.enchantment",
                ][..],
                (1, 1),
            ),
            (
                &[
                    "modal_mode.untap.pump.plus_one_power.indestructible",
                    "modal_mode.destroy.creature.power_at_least_four",
                ][..],
                (1, 1),
            ),
            (
                &[
                    "modal_mode.destroy.artifact_or_enchantment",
                    "modal_mode.explore.target_controlled.twice",
                ][..],
                (1, 1),
            ),
            (
                &[
                    "modal_mode.put_counter.plus_one.hexproof",
                    "modal_mode.destroy.creature.power_at_least_four",
                ][..],
                (1, 1),
            ),
            (
                &[
                    "modal_mode.destroy.creature.power_at_least_four",
                    "modal_mode.becomes_artifact.indestructible",
                ][..],
                (1, 1),
            ),
        ] {
            let recipe_ids = ids.iter().map(|id| RecipeId(id)).collect::<Vec<_>>();
            assert!(
                reviewed_modal_mode_pair(&recipe_ids, bounds.0, bounds.1),
                "{ids:?} must be reviewed at {bounds:?}"
            );
            assert!(
                !reviewed_modal_mode_pair(&recipe_ids, bounds.0, bounds.1 + 1),
                "{ids:?} must not accept widened bounds"
            );
        }

        // Reversed or partial sets stay fail-closed.
        for ids in [
            &[
                "modal_mode.reveal_hand_choose_nonland_discard",
                "modal_mode.discard.target_opponent.two",
            ][..],
            &["modal_mode.reveal_hand_choose_nonland_discard"][..],
            &[
                "modal_mode.discard.target_opponent.two",
                "modal_mode.reveal_hand_choose_nonland_discard",
                "modal_mode.destroy.enchantment",
            ][..],
            &[
                "modal_mode.look_top_four.one_hand_rest_graveyard",
                "modal_mode.counter.spell.unless_four",
            ][..],
            &[
                "modal_mode.counter.spell.unless_four",
                "modal_mode.look_top_four.one_hand_rest_graveyard",
            ][..],
        ] {
            let recipe_ids = ids.iter().map(|id| RecipeId(id)).collect::<Vec<_>>();
            assert!(
                !reviewed_modal_mode_pair(&recipe_ids, 1, 1),
                "{ids:?} must not be a reviewed mode set"
            );
        }
    }

    #[test]
    fn issue_426_reminder_bearing_modes_assemble_from_the_raw_bullet() {
        // Over the Edge's explore reminder is part of the matching contract, so the generation
        // path must try the complete bullet before the reminder-stripped fallback.
        let bullets = vec![
            "• Destroy target artifact or enchantment.".to_string(),
            format!("• {ISSUE_426_OVER_THE_EDGE_CLAUSE}"),
        ];
        let mut labels = Vec::new();
        let (modes, recipe_ids, _) =
            crate::assemble_modal_modes(&bullets, 2, &context(), &mut labels)
                .expect("Over the Edge bullets should assemble");
        assert_eq!(
            recipe_ids,
            [
                RecipeId("modal_mode.destroy.artifact_or_enchantment"),
                RecipeId("modal_mode.explore.target_controlled.twice"),
            ]
        );
        assert_eq!(modes.len(), 2);
        assert_eq!(modes[1].effects.len(), 2);
        assert!(matches!(
            modes[1].effects.as_slice(),
            [
                SpellEffectKind::Explore {
                    subject: EffectSubject::Chosen(_)
                },
                SpellEffectKind::Explore {
                    subject: EffectSubject::Chosen(_)
                }
            ]
        ));

        // The reminder-stripped bullet still resolves through the fallback for ordinary recipes.
        let stripped = vec![
            "• Draw a card.".to_string(),
            "• Target opponent discards two cards.".to_string(),
        ];
        let mut labels = Vec::new();
        let (modes, recipe_ids, _) =
            crate::assemble_modal_modes(&stripped, 2, &context(), &mut labels)
                .expect("ordinary bullets should assemble");
        assert_eq!(
            recipe_ids,
            [
                RecipeId("modal_mode.draw.one"),
                RecipeId("modal_mode.discard.target_opponent.two"),
            ]
        );
        assert_eq!(modes.len(), 2);
    }

    // -----------------------------------------------------------------------
    // Issue #424 — the triggered `When this creature enters, choose one —` batch.
    // -----------------------------------------------------------------------

    fn issue_424_modal_mode(
        source_name: &str,
        clause: &str,
        expected_id: &str,
    ) -> ModalModeEmission {
        let mut test_context = context();
        test_context.source_name = source_name.into();
        let matched = match_modal_mode(clause, &test_context)
            .unwrap_or_else(|error| panic!("{clause}: {error}"))
            .unwrap_or_else(|| panic!("missing modal_mode recipe for {clause}"));
        assert_eq!(matched.id.as_str(), expected_id, "{clause}");
        let RecipeEmission::ModalMode(emission) = matched.emission else {
            panic!("{expected_id} must emit a modal mode");
        };
        emission
    }

