    #[test]
    fn issue_428_choose_two_mode_recipes_reject_near_misses() {
        for (positive, near_misses) in [
            (
                "Create a token that's a copy of target Elemental you control.",
                &[
                    "Create a token that's a copy of target creature you control.",
                    "Create a token that's a copy of target Elemental.",
                    "Create a token that's a copy of target Elemental an opponent controls.",
                    "Create two tokens that are copies of target Elemental you control.",
                    "Create a token that's a copy of target Soldier you control.",
                    "Create a token that's a copy of target Elemental you control. It has haste.",
                ][..],
            ),
            (
                "Target player draws two cards.",
                &[
                    "Target player draws two cards and loses 3 life.",
                    "Target player draws three cards.",
                    "Each player draws two cards.",
                    "Target player draws two cards. You gain 2 life.",
                    "Target opponent draws two cards.",
                ][..],
            ),
            (
                "Target player draws a card.",
                &[
                    "Target player draws three cards.",
                    "Target opponent draws a card.",
                    "Target player draws a card and loses 1 life.",
                    "Each player draws a card.",
                ][..],
            ),
            (
                "Target creature you control gets +3/+3 until end of turn.",
                &[
                    "Target creature you control gets +4/+4 until end of turn.",
                    "Target creature you control gets +3/+0 until end of turn.",
                    "Target creature an opponent controls gets +3/+3 until end of turn.",
                    "Target creature you control gets +3/+3 and gains trample until end of turn.",
                    "Up to one target creature you control gets +3/+3 until end of turn.",
                ][..],
            ),
            (
                "Destroy target artifact or creature.",
                &[
                    "Destroy target artifact or planeswalker.",
                    "Destroy target noncreature artifact or creature.",
                    "Destroy up to one target artifact or creature.",
                    "Destroy target artifact or creature. You gain 1 life.",
                ][..],
            ),
            (
                "Destroy target creature or enchantment.",
                &[
                    "Destroy target creature or planeswalker.",
                    "Destroy target creature or artifact.",
                    "Destroy up to one target creature or enchantment.",
                    "Destroy target creature or enchantment. You gain 1 life.",
                ][..],
            ),
            (
                "Search your library for a basic land card, put it onto the battlefield tapped, then shuffle.",
                &[
                    "Search your library for a basic land card, put it onto the battlefield, then shuffle.",
                    "Search your library for a land card, put it onto the battlefield tapped, then shuffle.",
                    "You may search your library for a basic land card, put it onto the battlefield tapped, then shuffle.",
                    "Search your library for up to two basic land cards, put them onto the battlefield tapped, then shuffle.",
                    "Search your library for a basic land card, reveal it, put it into your hand, then shuffle.",
                ][..],
            ),
            (
                "Create a 1/1 white Human creature token.",
                &[
                    "Create two 1/1 white Human creature tokens.",
                    "Create a 1/1 white Human creature token with lifelink.",
                    "Create a 1/1 white Soldier creature token.",
                    "Create a 1/1 green and white Kithkin creature token.",
                ][..],
            ),
            (
                "Create a Food token.",
                &[
                    "Create two Food tokens.",
                    "Create a tapped Food token.",
                    "Create a Food token. You gain 3 life.",
                    "Create a Clue token.",
                ][..],
            ),
            (
                "Tap target creature. Put a stun counter on it.",
                &[
                    "Tap target creature. Put two stun counters on it.",
                    "Tap target permanent. Put a stun counter on it.",
                    "Tap target creature. Put a stun counter on it. Draw a card.",
                    "Tap target creature. Then put a stun counter on it.",
                ][..],
            ),
        ] {
            assert!(
                issue_428_modal_mode(positive).is_some(),
                "expected positive must match: {positive:?}"
            );
            for near_miss in near_misses {
                assert!(
                    issue_428_modal_mode(near_miss).is_none(),
                    "near-miss must stay unsupported: {near_miss:?}"
                );
            }
        }
    }

    // Issue #455 reviewed ETB opponent-pump identity clauses. The first row is the shipped
    // `-2/-0` singleton (Cogwork Wrestler, Humbling Elder); the other three are the newly
    // admitted Standard identities with their own reviewed deltas.
    const ISSUE_455_ETB_PUMP_CLAUSES: [(&str, &str, &str, i32, i32); 4] = [
        (
            "Cogwork Wrestler",
            "When this creature enters, target creature an opponent controls gets -2/-0 until end of turn.",
            "etb.pump.opponent_creature.minus_two_zero",
            -2,
            0,
        ),
        (
            "Burrog Befuddler",
            "When this creature enters, target creature an opponent controls gets -1/-0 until end of turn.",
            "etb.pump.opponent_creature.minus_one_zero",
            -1,
            0,
        ),
        (
            "Ambush Gigapede",
            "When this creature enters, target creature an opponent controls gets -2/-2 until end of turn.",
            "etb.pump.opponent_creature.minus_two_two",
            -2,
            -2,
        ),
        (
            "Sinister Cryologist",
            "When this creature enters, target creature an opponent controls gets -3/-0 until end of turn.",
            "etb.pump.opponent_creature.minus_three_zero",
            -3,
            0,
        ),
    ];

    const ISSUE_455_ETB_PUMP_NEAR_MISSES: [&str; 16] = [
        "When this creature enters, target creature an opponent controls gets -1/-1 until end of turn.",
        "When this creature enters, target creature an opponent controls gets -3/-3 until end of turn.",
        "When this creature enters, target creature an opponent controls gets -0/-2 until end of turn.",
        "When this creature enters, up to one target creature an opponent controls gets -2/-2 until end of turn.",
        "When this creature enters, target creature gets -1/-0 until end of turn.",
        "When this creature dies, target creature an opponent controls gets -1/-0 until end of turn.",
        "When this creature enters, target creature an opponent controls gets +2/+0 until end of turn.",
        "When this creature enters, target creature an opponent controls gets -1/-0 until your next turn.",
        "When this creature enters, target creature an opponent controls gets -1/-0 until end of turn. Draw a card.",
        "When this creature enters, target creatures an opponent controls get -1/-0 until end of turn.",
        "When this creature enters, target creature an opponent controls gets 0/0 until end of turn.",
        "When this creature enters, target creature an opponent controls gets -1/-0 until end of turn",
        "When another creature enters, target creature an opponent controls gets -1/-0 until end of turn.",
        // Non-canonical numeric spellings the shared parser must reject: a leading zero, a
        // zero-delta pair, and an explicit `+` sign.
        "When this creature enters, target creature an opponent controls gets 04/-0 until end of turn.",
        "When this creature enters, target creature an opponent controls gets -0/-0 until end of turn.",
        "When this creature enters, target creature an opponent controls gets +1/-0 until end of turn.",
    ];

    #[test]
    fn issue_455_etb_opponent_pump_clauses_match_their_exact_recipe() {
        for (name, clause, id, _, _) in ISSUE_455_ETB_PUMP_CLAUSES {
            let mut source = context();
            source.source_name = name.into();
            let matched = match_clause(clause, false, &source)
                .unwrap_or_else(|ambiguity| panic!("{name}: {ambiguity}"))
                .unwrap_or_else(|| panic!("{name} must match {id}"));
            assert_eq!(matched.id.as_str(), id, "{name}");
        }
    }

    #[test]
    fn issue_455_etb_opponent_pump_keeps_the_shipped_minus_two_zero_identity() {
        let (name, clause, id, power, toughness) = ISSUE_455_ETB_PUMP_CLAUSES[0];
        let mut source = context();
        source.source_name = name.into();
        let matched = match_clause(clause, false, &source)
            .unwrap_or_else(|ambiguity| panic!("{name}: {ambiguity}"))
            .unwrap_or_else(|| panic!("{name} must stay consumed by {id}"));
        assert_eq!(matched.id.as_str(), id);
        let RecipeEmission::TriggeredAbility(ability) = matched.emission else {
            panic!("the pump trigger must emit a triggered ability");
        };
        assert_eq!(ability.trigger, TriggerCondition::WhenSelfEntersBattlefield);
        assert_eq!(
            ability.effect,
            vec![SpellEffectKind::PumpTarget {
                power,
                toughness,
                scale: None,
                subject: chosen_creature(TargetController::Opponent),
            }]
        );
    }

    #[test]
    fn issue_455_etb_opponent_pump_emits_a_typed_opponent_pump_target() {
        for (name, clause, id, power, toughness) in ISSUE_455_ETB_PUMP_CLAUSES {
            let mut source = context();
            source.source_name = name.into();
            let matched = match_clause(clause, false, &source)
                .unwrap_or_else(|ambiguity| panic!("{name}: {ambiguity}"))
                .unwrap_or_else(|| panic!("{name} must match {id}"));
            assert_eq!(matched.id.as_str(), id, "{name}");
            let RecipeEmission::TriggeredAbility(ability) = matched.emission else {
                panic!("{name} must emit a triggered ability");
            };
            assert_eq!(
                ability.trigger,
                TriggerCondition::WhenSelfEntersBattlefield,
                "{name}"
            );
            assert_eq!(
                ability.effect,
                vec![SpellEffectKind::PumpTarget {
                    power,
                    toughness,
                    scale: None,
                    subject: chosen_creature(TargetController::Opponent),
                }],
                "{name}"
            );
            assert_eq!(
                ability.targeting,
                Some(exact_targeting(
                    1,
                    1,
                    "Choose target creature an opponent controls",
                    vec![0],
                )),
                "{name}"
            );
            assert!(!ability.may, "{name}");
        }
    }

    #[test]
    fn issue_455_etb_opponent_pump_rejects_near_misses() {
        let rejects_family = |text: &str| {
            [
                match_etb_pump_opponent_creature_minus_two_zero,
                match_etb_pump_opponent_creature_minus_one_zero,
                match_etb_pump_opponent_creature_minus_two_two,
                match_etb_pump_opponent_creature_minus_three_zero,
            ]
            .iter()
            .all(|matcher| (matcher)(text, &context()).is_none())
        };
        for negative in ISSUE_455_ETB_PUMP_NEAR_MISSES {
            assert!(
                rejects_family(negative),
                "the shared ETB pump family must reject {negative:?}"
            );
            assert!(
                match_clause(negative, false, &context())
                    .unwrap_or_else(|ambiguity| panic!("{negative}: {ambiguity}"))
                    .is_none(),
                "unsupported near-miss must remain unmatched: {negative}"
            );
        }

        let mut noncreature = context();
        noncreature.source_is_creature = false;
        assert!(
            match_clause(ISSUE_455_ETB_PUMP_CLAUSES[1].1, false, &noncreature)
                .expect("noncreature source must not be ambiguous")
                .is_none(),
            "the pump trigger is creature-source-only"
        );
    }

    #[test]
    fn issue_455_recipes_have_stable_ids_and_surfaces() {
        for (_, _, id, _, _) in ISSUE_455_ETB_PUMP_CLAUSES {
            assert_eq!(
                issue_318_recipe(id).surface,
                RecipeSurface::EtbAbility,
                "{id} surface drifted"
            );
        }
    }

    /// The four retained Standard identities behind issue #456. Each prints `{T}: Add {C}.`
    /// followed by the exact conditional pair clause with its reviewed printed color order.
    const ISSUE_456_CONDITIONAL_PAIR_MANA_CLAUSES: [(&str, char, char); 4] = [
        ("Dark Fortress", 'B', 'R'),
        ("Gathering Place", 'G', 'W'),
        ("Training Compound", 'R', 'G'),
        ("Gleaming Bastion", 'W', 'U'),
    ];

    const ISSUE_456_CONDITIONAL_PAIR_MANA_SUFFIX: &str =
        ". Activate only if this land entered this turn or if you control a basic land.";

    fn issue_456_clause(first: char, second: char) -> String {
        format!("{{T}}: Add {{{first}}} or {{{second}}}{ISSUE_456_CONDITIONAL_PAIR_MANA_SUFFIX}")
    }

    /// The exact Hidden Lair condition shape: either the source's own entry this turn or a
    /// controller-controlled basic land.
    fn issue_456_condition() -> GameCondition {
        GameCondition::AnyOf(vec![
            GameCondition::PermanentsEnteredThisTurn {
                controllers: RelativePlayerSet::All,
                filter: PermanentEventFilter {
                    source_only: true,
                    ..PermanentEventFilter::default()
                },
                min: Some(1),
                max: None,
            },
            GameCondition::BattlefieldAggregate {
                filter: BattlefieldPermanentFilter {
                    token: None,
                    any_of: None,
                    controllers: RelativePlayerSet::Controller,
                    card_type: Some(CardTypeFilter::BasicLand),
                    color: None,
                    name: None,
                    required_subtypes: Vec::new(),
                    exclude_source: false,
                },
                aggregate: BattlefieldAggregate::Count,
                min: Some(1),
                max: None,
            },
        ])
    }

    #[test]
    fn issue_456_conditional_pair_mana_clauses_match_their_exact_recipe() {
        for (name, first, second) in ISSUE_456_CONDITIONAL_PAIR_MANA_CLAUSES {
            let clause = issue_456_clause(first, second);
            let mut source = context();
            source.source_name = name.into();
            let matched = match_clause(&clause, false, &source)
                .unwrap_or_else(|ambiguity| panic!("{name}: {ambiguity}"))
                .unwrap_or_else(|| panic!("{name} must match activated.tap.conditional_pair_mana"));
            assert_eq!(
                matched.id.as_str(),
                "activated.tap.conditional_pair_mana",
                "{name}"
            );
            let RecipeEmission::ActivatedAbility(ability) = matched.emission else {
                panic!("{name} must emit an activated ability");
            };
            assert_eq!(
                ability.source_zone,
                AbilitySourceZone::Battlefield,
                "{name}"
            );
            assert_eq!(ability.costs, vec![AbilityCost::Tap], "{name}");
            assert_eq!(
                ability.effect,
                vec![SpellEffectKind::ProduceMana {
                    options: vec![
                        parse_mana_amount(first).expect("reviewed color symbol"),
                        parse_mana_amount(second).expect("reviewed color symbol"),
                    ],
                    restriction: None,
                    conditional: None,
                }],
                "{name}"
            );
            assert_eq!(ability.conditions, vec![issue_456_condition()], "{name}");
            assert!(ability.cost_modifiers.is_empty(), "{name}");
            assert!(ability.targeting.is_none(), "{name}");
            assert_eq!(ability.timing, ActivationTiming::Normal, "{name}");
            assert!(ability.activation_limit.is_none(), "{name}");
        }
    }

    #[test]
    fn issue_456_conditional_pair_mana_is_activated_only() {
        let clause = issue_456_clause('B', 'R');
        assert!(
            match_clause(&clause, true, &context())
                .expect("spell surface check must not be ambiguous")
                .is_none(),
            "the conditional pair ability is not a spell clause"
        );
    }

    #[test]
    fn issue_456_conditional_pair_mana_rejects_near_misses() {
        for negative in [
            // The handwritten Hidden Lair identity ({U}/{B}) stays unclaimed.
            issue_456_clause('U', 'B'),
            // Same-color and colorless pairs.
            issue_456_clause('B', 'B'),
            "{T}: Add {C} or {R}. Activate only if this land entered this turn or if you control a basic land.".to_string(),
            // Reversed and unknown symbol pairs.
            issue_456_clause('R', 'B'),
            "{T}: Add {W/U} or {B}. Activate only if this land entered this turn or if you control a basic land.".to_string(),
            // Subset conditions.
            "{T}: Add {B} or {R}. Activate only if this land entered this turn.".to_string(),
            "{T}: Add {B} or {R}. Activate only if you control a basic land.".to_string(),
            // Timing restriction.
            "{T}: Add {B} or {R}. Activate only as a sorcery.".to_string(),
            // Mana-cost prefix.
            "{1}, {T}: Add {B} or {R}. Activate only if this land entered this turn or if you control a basic land.".to_string(),
            // Missing trailing period and an appended rider.
            "{T}: Add {B} or {R}. Activate only if this land entered this turn or if you control a basic land".to_string(),
            "{T}: Add {B} or {R}. Activate only if this land entered this turn or if you control a basic land. Draw a card.".to_string(),
        ] {
            assert!(
                match_activated_tap_conditional_pair_mana(&negative, &context()).is_none(),
                "the new family must reject {negative:?}"
            );
            issue_318_assert_unmatched(&negative, false);
        }

        let mut nonland = context();
        nonland.source_is_land = false;
        assert!(
            match_clause(&issue_456_clause('B', 'R'), false, &nonland)
                .expect("nonland source check must not be ambiguous")
                .is_none(),
            "the conditional pair ability is land-source-only"
        );
    }

    #[test]
    fn issue_456_shipped_unconditional_pair_mana_keeps_its_identity() {
        for (first, second) in [('B', 'R'), ('G', 'W'), ('R', 'G'), ('W', 'U')] {
            let clause = format!("{{T}}: Add {{{first}}} or {{{second}}}.");
            let matched = match_clause(&clause, false, &context())
                .unwrap_or_else(|ambiguity| panic!("{clause}: {ambiguity}"))
                .unwrap_or_else(|| panic!("{clause} must stay consumed by the shipped recipe"));
            assert_eq!(
                matched.id.as_str(),
                "activated.mana.tap_two_or_three_colors",
                "{clause}"
            );
        }

        let hidden_lair = issue_456_clause('U', 'B');
        assert!(
            match_clause(&hidden_lair, false, &context())
                .expect("Hidden Lair clause check must not be ambiguous")
                .is_none(),
            "the handwritten Hidden Lair clause must remain unclaimed"
        );
        assert!(
            match_activated_tap_conditional_pair_mana("{T}: Add {B} or {R}.", &context()).is_none(),
            "the unconditional pair line is owned by the shipped multicolor recipe"
        );
    }

    #[test]
    fn issue_456_recipes_have_stable_ids_and_surfaces() {
        assert_eq!(
            issue_318_recipe("activated.tap.conditional_pair_mana").surface,
            RecipeSurface::ActivatedAbility
        );
    }

    // -----------------------------------------------------------------------
    // Issue #457 — the Power-up and Exhaust two-counter activation family.
    //
    // Each reviewed identity prints exactly
    // `<Keyword> — {cost}: Put two +1/+1 counters on this creature.` plus reminder text. The
    // recognizer owns the reminder-stripped sentence, so the helper below replays the generator's
    // raw-line-then-stripped-line fallback instead of pre-stripping the fixture input.
    // -----------------------------------------------------------------------

    /// `(name, recipe id, printed activation cost, complete printed Oracle line)`.
    const ISSUE_457_TWO_COUNTER_CLAUSES: [(&str, &str, &str, &str); 5] = [
        (
            "Serpent Specialist",
            "activated.power_up.two_counters",
            "{3}{G}",
            "Power-up — {3}{G}: Put two +1/+1 counters on this creature. (Activate each power-up ability only once. Reduce the cost by its mana cost if it entered this turn.)",
        ),
        (
            "Brave Brawler",
            "activated.power_up.two_counters",
            "{4}{W}",
            "Power-up — {4}{W}: Put two +1/+1 counters on this creature. (Activate each power-up ability only once. Reduce the cost by its mana cost if it entered this turn.)",
        ),
        (
            "Volcanic Villain",
            "activated.power_up.two_counters",
            "{5}{R}",
            "Power-up — {5}{R}: Put two +1/+1 counters on this creature. (Activate each power-up ability only once. Reduce the cost by its mana cost if it entered this turn.)",
        ),
        (
            "Prowcatcher Specialist",
            "activated.exhaust.two_counters",
            "{3}{R}",
            "Exhaust — {3}{R}: Put two +1/+1 counters on this creature. (Activate each exhaust ability only once.)",
        ),
        (
            "Skystreak Engineer",
            "activated.exhaust.two_counters",
            "{4}{U}",
            "Exhaust — {4}{U}: Put two +1/+1 counters on this creature. (Activate each exhaust ability only once.)",
        ),
    ];

    fn issue_457_match_printed_line(name: &str, line: &str) -> Option<RecipeMatch> {
        let mut source = context();
        source.source_name = name.into();
        match_clause(line.trim(), false, &source)
            .unwrap_or_else(|ambiguity| panic!("{name}: {ambiguity}"))
            .or_else(|| {
                match_clause(crate::strip_reminder(line).trim(), false, &source)
                    .unwrap_or_else(|ambiguity| panic!("{name}: {ambiguity}"))
            })
    }

    /// The handwritten anchors (`ultron_drone.ron`, `rebellious_captives.ron`) use this exact
    /// Power-up reduction shape.
    fn issue_457_power_up_reduction() -> ActivatedCostModifier {
        ActivatedCostModifier::ConditionalSourceManaCostReduction {
            condition: GameCondition::PermanentsEnteredThisTurn {
                controllers: RelativePlayerSet::All,
                filter: PermanentEventFilter {
                    source_only: true,
                    ..PermanentEventFilter::default()
                },
                min: Some(1),
                max: None,
            },
        }
    }

    #[test]
    fn issue_457_two_counter_clauses_match_their_exact_recipe() {
        for (name, recipe_id, cost, line) in ISSUE_457_TWO_COUNTER_CLAUSES {
            let matched = issue_457_match_printed_line(name, line)
                .unwrap_or_else(|| panic!("{name} must match {recipe_id}"));
            assert_eq!(matched.id.as_str(), recipe_id, "{name}");
            let RecipeEmission::ActivatedAbility(ability) = matched.emission else {
                panic!("{name} must emit an activated ability");
            };
            assert_eq!(ability.ability_id.as_str(), "activated_01", "{name}");
            assert_eq!(
                ability.source_zone,
                AbilitySourceZone::Battlefield,
                "{name}"
            );
            assert_eq!(
                ability.costs,
                vec![AbilityCost::Mana(
                    ManaCost::parse(cost).expect("reviewed printed mana cost")
                )],
                "{name}"
            );
            assert_eq!(
                ability.effect,
                vec![SpellEffectKind::PutCounters {
                    counter: CounterKind::PlusOnePlusOne,
                    count: Amount::Fixed(2),
                    subject: EffectSubject::Source,
                }],
                "{name}"
            );
            assert_eq!(
                ability.activation_limit,
                Some(ActivationLimit::PerObject { max_activations: 1 }),
                "{name}"
            );
            assert!(ability.targeting.is_none(), "{name}");
            assert_eq!(ability.timing, ActivationTiming::Normal, "{name}");
            assert!(ability.conditions.is_empty(), "{name}");
            let expected_modifiers = if recipe_id == "activated.power_up.two_counters" {
                vec![issue_457_power_up_reduction()]
            } else {
                Vec::new()
            };
            assert_eq!(ability.cost_modifiers, expected_modifiers, "{name}");
        }
    }

    #[test]
    fn issue_457_power_up_and_exhaust_forms_stay_disjoint() {
        let power_up = "Power-up — {3}{G}: Put two +1/+1 counters on this creature.";
        let exhaust = "Exhaust — {3}{R}: Put two +1/+1 counters on this creature.";
        let power_match = issue_457_match_printed_line("Serpent Specialist", power_up)
            .expect("the Power-up sentence must match its own recipe");
        assert_eq!(power_match.id.as_str(), "activated.power_up.two_counters");
        let exhaust_match = issue_457_match_printed_line("Prowcatcher Specialist", exhaust)
            .expect("the Exhaust sentence must match its own recipe");
        assert_eq!(exhaust_match.id.as_str(), "activated.exhaust.two_counters");
        assert_ne!(power_match.id, exhaust_match.id);
    }

    #[test]
    fn issue_457_two_counter_family_rejects_near_misses() {
        for negative in [
            // The bare sentence without a keyword prefix stays unclaimed.
            "{3}{G}: Put two +1/+1 counters on this creature.",
            // Another counter count, a target recipient, and an appended rider.
            "Power-up — {3}{G}: Put a +1/+1 counter on this creature.",
            "Power-up — {3}{G}: Put two +1/+1 counters on target creature.",
            "Power-up — {3}{G}: Put two +1/+1 counters on this creature. Draw a card.",
            "Exhaust — {3}{R}: Put a +1/+1 counter on this creature.",
            "Exhaust — {3}{R}: Put two +1/+1 counters on target creature.",
            "Exhaust — {3}{R}: Put two +1/+1 counters on this creature. It gains trample until end of turn.",
            // Reordered, duplicated, generic-only, and X-bearing symbol strings. The duplicated
            // color form keeps Afterburner Expert ({2}{G}{G}) unclaimed and the generic-only form
            // keeps Hog-Monkey ({5}) unclaimed.
            "Power-up — {3}{G}{G}: Put two +1/+1 counters on this creature.",
            "Exhaust — {2}{G}{G}: Put two +1/+1 counters on this creature.",
            "Power-up — {G}{3}: Put two +1/+1 counters on this creature.",
            "Power-up — {5}: Put two +1/+1 counters on this creature.",
            "Exhaust — {5}: Put two +1/+1 counters on this creature.",
            "Power-up — {X}{G}: Put two +1/+1 counters on this creature.",
            // Lowercase, joined, and different keyword spellings.
            "power-up — {3}{G}: Put two +1/+1 counters on this creature.",
            "Powerup — {3}{G}: Put two +1/+1 counters on this creature.",
            "exhaust — {3}{R}: Put two +1/+1 counters on this creature.",
            "Haste — {3}{G}: Put two +1/+1 counters on this creature.",
        ] {
            issue_318_assert_unmatched(negative, false);
        }
    }

    #[test]
    fn issue_457_two_counter_family_is_creature_source_only() {
        for (name, line) in [
            (
                "Serpent Specialist",
                "Power-up — {3}{G}: Put two +1/+1 counters on this creature.",
            ),
            (
                "Prowcatcher Specialist",
                "Exhaust — {3}{R}: Put two +1/+1 counters on this creature.",
            ),
        ] {
            let mut noncreature = context();
            noncreature.source_name = name.into();
            noncreature.source_is_creature = false;
            assert!(
                match_clause(line, false, &noncreature)
                    .expect("noncreature source check must not be ambiguous")
                    .is_none(),
                "{name} must not match a noncreature source"
            );
        }
    }

    #[test]
    fn issue_457_recipes_have_stable_ids_and_surfaces() {
        for id in [
            "activated.power_up.two_counters",
            "activated.exhaust.two_counters",
        ] {
            assert_eq!(
                issue_318_recipe(id).surface,
                RecipeSurface::ActivatedAbility,
                "{id} surface drifted"
            );
        }
    }

